import java.util.Map;
import java.util.stream.Collectors;

public class AnagramChecker {

    public boolean isAnagram(String s1, String s2) {
        if (s1 != null && s2 != null) {
            s1 = s1.trim();
            s2 = s2.trim();

            // If lengths are different, they can't be anagrams
            if (s1.length() != s2.length()) {
                return false;
            }

            // Creating character count maps for both strings
            Map<Character, Long> s1Map = s1.chars()
                    .mapToObj(c -> (char) c)
                    .collect(Collectors.groupingBy(c -> c, Collectors.counting()));

            Map<Character, Long> s2Map = s2.chars()
                    .mapToObj(c -> (char) c)
                    .collect(Collectors.groupingBy(c -> c, Collectors.counting()));

            // Compare both maps
            return s1Map.equals(s2Map);
        } else {
            return false;
        }
    }

    public static void main(String[] args) {
        AnagramChecker checker = new AnagramChecker();

        String s1 = "listen";
        String s2 = "silent";

        if (checker.isAnagram(s1, s2)) {
            System.out.println(s1 + " and " + s2 + " are anagrams.");
        } else {
            System.out.println(s1 + " and " + s2 + " are not anagrams.");
        }
    }
}
```

### Explanation of Fixes:
- The `s1.trim()` and `s2.trim()` are stored back in `s1` and `s2` to handle leading/trailing spaces.
- Changed `Collectors.counting()` to count each character's occurrences.
- Fixed `mapToObj(c -> (char) c)` to correctly convert the `int` stream from `chars()` into a stream of characters.
- Correctly compare the two maps using `.equals()` at the end.

