import { Request, Response } from 'express';
import students from '../models/studentModel';
import responseUtil from '../utils/response';

export const getAllStudents = (req: Request, res: Response): void => {
    new Promise((resolve, reject) => {
        try {
            resolve(students);
        } catch (error) {
            reject("Error fetching students");
        }
    })
    .then(result => {
        res.status(200).json(responseUtil.createResponse("All students retrieved", result, 200));
    })
    .catch(error => {
        res.status(500).json(responseUtil.createResponse(error, null, 500));
    });
};

export const getStudentById = (req: Request, res: Response): void => {
    new Promise((resolve, reject) => {
        const student = students.find(s => s.id === parseInt(req.params.id));
        if (!student) {
            reject("Student not found");
        } else {
            resolve(student);
        }
    })
    .then(result => {
        res.status(200).json(responseUtil.createResponse("Student retrieved", result, 200));
    })
    .catch(error => {
        res.status(404).json(responseUtil.createResponse(error, null, 404));
    });
};

export const createStudent = (req: Request, res: Response): void => {
    new Promise((resolve, reject) => {
        try {
            const newStudent = {
                id: students.length + 1,
                name: req.body.name,
                age: req.body.age,
                major: req.body.major
            };
            students.push(newStudent);
            resolve(newStudent);
        } catch (error) {
            reject("Error creating student");
        }
    })
    .then(result => {
        res.status(201).json(responseUtil.createResponse("Student created successfully", result, 201));
    })
    .catch(error => {
        res.status(500).json(responseUtil.createResponse(error, null, 500));
    });
};

export const updateStudent = (req: Request, res: Response): void => {
    new Promise((resolve, reject) => {
        const student = students.find(s => s.id === parseInt(req.params.id));
        if (!student) {
            reject("Student not found");
        } else {
            student.name = req.body.name;
            student.age = req.body.age;
            student.major = req.body.major;
            resolve(student);
        }
    })
    .then(result => {
        res.status(200).json(responseUtil.createResponse("Student updated successfully", result, 200));
    })
    .catch(error => {
        res.status(404).json(responseUtil.createResponse(error, null, 404));
    });
};

export const deleteStudent = (req: Request, res: Response): void => {
    new Promise((resolve, reject) => {
        const studentIndex = students.findIndex(s => s.id === parseInt(req.params.id));
        if (studentIndex === -1) {
            reject("Student not found");
        } else {
            const deletedStudent = students.splice(studentIndex, 1);
            resolve(deletedStudent[0]);
        }
    })
    .then(result => {
        res.status(200).json(responseUtil.createResponse("Student deleted successfully", result, 200));
    })
    .catch(error => {
        res.status(404).json(responseUtil.createResponse(error, null, 404));
    });
};
```

