    backgroundColor: "#fff",
    padding: "20px",
    borderRadius: "10px",
    textAlign: "center" as "center",
  },
};

export default OverlayModal;
```

### 2. Update the Hook to Control the Modal

You can enhance your hook to manage the global loading and error states, returning the `loading`, `error`, and `fetchData` while showing or hiding the modal.

```tsx
import { useState, useCallback } from "react";
import OverlayModal from "./OverlayModal";  // Assuming you saved the modal as OverlayModal

interface ApiResponse<T> {
  status: "SUCCESS" | "VALIDATION_ERROR" | "DATABASE_ERROR" | "ERROR";
  messages: string[];
  data: T | null;
  statusCode: number;
  timeStamp: string;
}

type FetchOptions = {
  method?: "GET" | "POST" | "PUT" | "DELETE";
  headers?: Record<string, string>;
  body?: unknown;
};

export const useApiRequest = <T extends string | number>(
  url: string,
  options?: FetchOptions
) => {
  const [result, setResult] = useState<ApiResponse<T | null> | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(url, {
        method: options?.method || "GET",
        headers: {
          "Content-Type": "application/json",
          ...options?.headers,
        },
        body: options?.body ? JSON.stringify(options.body) : undefined,
      });

      const responseJson: ApiResponse<T> = await response.json();

      if (response.ok && responseJson.status === "SUCCESS") {
        setResult(responseJson);
      } else {
        setError(responseJson.messages.join(", "));
      }
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setLoading(false);
    }
  }, [url, options]);

  return { result, error, loading, fetchData };
};
```

### 3. Implement in Your Components

Now, in any component, you can use the hook to trigger the modal when loading or an error occurs.

```tsx
import React, { useEffect } from "react";
import { useApiRequest } from "./useApiRequest";
import OverlayModal from "./OverlayModal";

const BaseURL = "http://127.0.0.1:3003/tweets/v2";

const MyComponent = () => {
  const { result, error, loading, fetchData } = useApiRequest(BaseURL);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  return (
    <div>
      <h1>MyComponent</h1>

      {/* Overlay modal for loading and error */}
      <OverlayModal loading={loading} error={error} />

      {result && !loading && !error && (
        <p>
          Result: {result.statusCode}, <br />
          Messages: {result.messages.join(", ")}, <br />
          ApiResponse data: {JSON.stringify(result.data)}, <br />
          Type of ApiResponse data: {typeof result.data}
          <br />
        </p>
      )}
    </div>
  );
};

export default MyComponent;
```

### Benefits:
1. **Reusability**: You can reuse this modal and hook in multiple components, managing all loading and error states centrally.
2. **Cleaner UI**: Instead of handling loading/error messages inside every component, the modal handles it globally.
3. **Flexibility**: You can easily extend the hook and modal to support more complex error handling or different UI themes.

This pattern is scalable and improves code consistency across the app.

