import Input from "@/components/common/custom-input/CustomInputV3";
import { useGlobalStyles } from "@/common/hooks/useGlobalStyles";

interface ApiResponse<T> {
  status: "SUCCESS" | "VALIDATION_ERROR" | "DATABASE_ERROR" | "ERROR";
  messages: string[];
  data: T | null;
  statusCode: number;
  timeStamp: string;
}

const default_Delay_In_MS = 300;

function getRandomNumberBetween0andGivenNumber(num: number): number {
  return Math.floor(Math.random() * num);
}

// Helper function to create the ApiResponse object
function getApiResponse<T>(
  status: ApiResponse<T>["status"],
  message: string,
  data: T | null,
  statusCode: number
): ApiResponse<T> {
  return {
    status,
    messages: [message],
    data,
    statusCode,
    timeStamp: new Date().toISOString(),
  };
}

// Extract reusable async operation logic
function performAsyncOperation<T extends string | number>(
  requestObjectType: string | number,
  setError: React.Dispatch<React.SetStateAction<string | null>>,
  setLoading: React.Dispatch<React.SetStateAction<boolean>>,
  setResult: React.Dispatch<React.SetStateAction<ApiResponse<T> | null>>,
  delay: number = default_Delay_In_MS,
  shouldError: boolean = false
) {
  setLoading(true);
  setError(null);

  const computedDelay = delay >= default_Delay_In_MS ? delay : default_Delay_In_MS;

  setTimeout(() => {
    if (shouldError) {
      const res = "An error occurred while computing value";
      setError(res);
      setLoading(false);
      setResult(getApiResponse("ERROR", res, null, 500));
    } else {
      const validationFailed = !requestObjectType;
      const responseMessage = requestObjectType
        ? `Response for given requestObjectType: '${requestObjectType}', after ${computedDelay} milliseconds`
        : "Unable to perform action, as null or empty value provided";
      const data = (typeof requestObjectType === "string" ? "India is great!!" : 2024) as T;
      setLoading(false);
      setResult(
        getApiResponse(
          validationFailed ? "VALIDATION_ERROR" : "SUCCESS",
          responseMessage,
          validationFailed ? null : data,
          validationFailed ? 404 : 200
        )
      );
    }
  }, computedDelay);
}

const AppWithCustomAPIHookV1_0_1 = () => {
  const {
    GLOBAL_APPLICATION_STYLES: { main, testComponentV2 },
  } = useGlobalStyles();

  const [result, setResult] = useState<ApiResponse<string | number> | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  // Array of actions to trigger different async operations
  const actions = [
    () => performAsyncOperation("String", setError, setLoading, setResult),
    () => performAsyncOperation(3, setError, setLoading, setResult),
    () => performAsyncOperation("", setError, setLoading, setResult),
  ];

  const handleClick = () => {
    actions[getRandomNumberBetween0andGivenNumber(actions.length)]();
  };

  return (
    <div className={`${main}`}>
      <h1>AppWithCustomAPIHookV1_0_1</h1>

      <button onClick={handleClick} disabled={loading}>
        {loading ? "Processing..." : "Execute"}
      </button>

      {loading && <p>Loading...</p>}
      {error && <p style={{ color: "red" }}>Error: {error}</p>}
      {result && !loading && !error && (
        <p>
          Result: {result.statusCode}, {result.messages.join(", ")},{" "}
          {JSON.stringify(result.data)}
        </p>
      )}
    </div>
  );
};

export default AppWithCustomAPIHookV1_0_1;
```

### Refactor Summary:
1. **`getApiResponse`**: A helper function that generates the API response object.
2. **`performAsyncOperation`**: A reusable function that handles the async logic. It now accepts `setError`, `setLoading`, and `setResult` as parameters to update the state directly.
3. **`handleClick`**: Triggers a random action by choosing one from the `actions` array.

Ah, I see! You were referring to `classNames` as a JSX attribute, not the library. The `classNames` attribute is not a valid HTML or React attribute. You should always use `className` in JSX for setting CSS classes. The `classNames` library I mentioned earlier is a utility for combining class names, but it doesn't replace the `className` attribute.

### Correct Usage in JSX

In JSX, the correct way to apply CSS classes to an element is using the `className` attribute:

```tsx
import React from 'react';
import Post from '../post/Post';
import { useGlobalStyles } from '@/common/utils/useGlobalStyles';

const PostsList = () => {
  const { GLOBAL_APPLICATION_STYLES: { ul, posts } } = useGlobalStyles();

  return (
    <ul className={`${ul} ${posts}`}>
      <Post author='Premendra Kumar' body='Practice makes a man perfect' />
      <Post author='Vandana Kumari' body='I will become a teacher in next birth' />
    </ul>
  );
}

export default PostsList;
```

### Summary
- **Use `className`**: This is the standard attribute for applying CSS classes to HTML elements in React.
- **Do not use `classNames` as an attribute**: It's not valid. Use the `classNames` library for dynamically combining class names in your JavaScript/TypeScript code, but always apply them using the `className` attribute in JSX.

There are a few issues in your code that need to be addressed:

1. **Type Assertion**: You are trying to directly assign the `rawStyles` object to the `GlobalStyleProps` type. This will not work as TypeScript cannot verify the structure of `rawStyles` automatically. You need to use a type assertion or cast.

2. **Naming**: You're creating a `styles` object inside `getStyles()` but then destructuring it immediately. This is unnecessary and can be simplified.

3. **Type-Correctness**: If any property is missing in `rawStyles`, TypeScript will raise an issue. You need to handle that or ensure that `rawStyles` contains all keys defined in `GlobalStyleProps`.

