### 2. Modify the Hook to Manage and Render the Modal Directly
This updated hook will now manage both the modal's visibility and the API request logic.

```tsx
import { useState, useCallback } from "react";
import OverlayModal from "./OverlayModal";

interface ApiResponse<T> {
  status: "SUCCESS" | "VALIDATION_ERROR" | "DATABASE_ERROR" | "ERROR";
  messages: string[];
  data: T | null;
  statusCode: number;
  timeStamp: string;
}

type FetchOptions = {
  method?: "GET" | "POST" | "PUT" | "DELETE";
  headers?: Record<string, string>;
  body?: unknown;
};

export const useApiRequest = <T extends string | number>(
  url: string,
  options?: FetchOptions
) => {
  const [result, setResult] = useState<ApiResponse<T | null> | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(url, {
        method: options?.method || "GET",
        headers: {
          "Content-Type": "application/json",
          ...options?.headers,
        },
        body: options?.body ? JSON.stringify(options.body) : undefined,
      });

      const responseJson: ApiResponse<T> = await response.json();

      if (response.ok && responseJson.status === "SUCCESS") {
        setResult(responseJson);
      } else {
        setError(responseJson.messages.join(", "));
      }
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setLoading(false);
    }
  }, [url, options]);

  // Inject the overlay modal directly inside the hook
  const overlayModal = (
    <OverlayModal loading={loading} error={error} />
  );

  return { result, error, loading, fetchData, overlayModal };
};
```

### 3. Use the Hook in a Component Without Directly Managing the Overlay
Now, when using the hook in any component, the modal will be rendered automatically when the hook is invoked. The component doesn't need to handle `loading` or `error` states anymore.

```tsx
import React, { useEffect } from "react";
import { useApiRequest } from "./useApiRequest";

const BaseURL = "http://127.0.0.1:3003/tweets/v2";

const MyComponent = () => {
  const { result, fetchData, overlayModal } = useApiRequest(BaseURL);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  return (
    <div>
      <h1>MyComponent</h1>

      {/* Overlay modal will automatically render */}
      {overlayModal}

      {result && (
        <p>
          Result: {result.statusCode}, <br />
          Messages: {result.messages.join(", ")}, <br />
          ApiResponse data: {JSON.stringify(result.data)}, <br />
          Type of ApiResponse data: {typeof result.data}
        </p>
      )}
    </div>
  );
};

export default MyComponent;
```

### How This Works:
1. **Centralized management**: The `useApiRequest` hook handles the `loading` and `error` states, and it manages the modal. Components no longer need to worry about managing these states or showing the modal manually.
2. **Reusability**: The modal and API logic are encapsulated in the hook, so you can reuse this across different components and for different API requests.
3. **Scalability**: If you need to customize the modal further (e.g., adding custom error handling or additional statuses like warnings), you can easily extend this without modifying each component.

Now, every time you invoke the `fetchData` method from the hook, the modal will automatically display the loading/error states centrally.

