  }

  for (const key in json) {
    if (json.hasOwnProperty(key)) {
      const value = json[key];
      typeDef += `  ${key}: ${inferType(value, key)};\n`;
    }
  }

  typeDef += `}\n`;

  // Add the current type definition to the list
  typesList.push(typeDef);

  return { typeName, typesList };
};

// Public method to infer the type based on input, exposed directly
export const tellTheType = (value: any): { typeName: string; typesList: string[] } => {
  if (Array.isArray(value)) {
    if (value.length > 0) {
      const elementType = tellTheType(value[0]);
      return {
        typeName: `${elementType.typeName}[]`,
        typesList: elementType.typesList,
      };
    } else {
      return { typeName: `any[]`, typesList: [] }; // If the array is empty, return any[]
    }
  } else if (value === null) {
    return { typeName: "null", typesList: [] };
  } else if (typeof value === "object") {
    // When the type is an object, call generateTypeFromJson to handle it
    return generateTypeFromJson(value, "RootType"); // Use "RootType" as the default type name
  } else {
    return { typeName: typeof value, typesList: [] };
  }
};
```

### Key Features
1. **Nested Type Handling**:
   - When an object is encountered, it generates a unique nested type name (e.g., `RootType_Metadata`) and includes its definition in the `typesList`.

2. **Updated `typesList`**:
   - Each time a nested type is created, it's added to the `typesList`, ensuring that the output includes all relevant type definitions.

### Output Example

For the given input:

```json
{
  "id": 1,
  "name": "Sample",
  "tags": ["typescript", "json"],
  "metadata": {
    "createdBy": "Admin",
    "createdAt": "2024-01-01"
  },
  "isActive": true
}
```

The output will include the `Metadata` type as follows:

```json
{
  "guessedType": {
    "typeName": "RootType",
    "typesList": [
      "interface RootType {\n  id: number;\n  name: string;\n  tags: string[];\n  metadata: Metadata;\n  isActive: boolean;\n}\n",
      "interface Metadata {\n  createdBy: string;\n  createdAt: string;\n}\n"
    ]
  }
}
```

### Final Notes
- Ensure that you handle any additional nested objects properly within `inferType` to maintain clear type definitions.
- This structure keeps the `generateTypeFromJson` method encapsulated while allowing `tellTheType` to generate types for both root and nested objects seamlessly.

