  name: "Sample",
  tags: ["typescript", "json"],
  metadata: {
    createdBy: "Admin",
    createdAt: "2024-01-01"
  },
  isActive: true
};

const result = tellTheType(sampleJson);
console.log(JSON.stringify(result, null, 2));
```

