Here's a custom hook `useFetch` that you can use to perform generic `fetch` requests. The hook is designed to handle different types of response data. You can use this hook in your `PostsListV11` component and elsewhere.

### `useFetch` Hook

```tsx
import { useState, useEffect } from "react";

interface ApiResponse<T> {
  status: "SUCCESS" | "VALIDATION_ERROR" | "DATABASE_ERROR" | "ERROR";
  messages: string[];
  data: T | null;
  statusCode: number;
  timeStamp: string;
}

type FetchOptions = {
  method?: "GET" | "POST" | "PUT" | "DELETE";
  headers?: Record<string, string>;
  body?: unknown;
};

export const useFetch = <T,>(url: string, options?: FetchOptions) => {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const response = await fetch(url, {
          method: options?.method || "GET",
          headers: {
            "Content-Type": "application/json",
            ...options?.headers,
          },
          body: options?.body ? JSON.stringify(options.body) : undefined,
        });

        const responseJson: ApiResponse<T> = await response.json();

        if (response.ok && responseJson.status === "SUCCESS") {
          setData(responseJson.data);
        } else {
          setError(responseJson.messages.join(", "));
        }
      } catch (err) {
        setError((err as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [url, options]);

  return { data, error, isLoading };
};
```

### Usage in `PostsListV11`

Now you can replace your `fetch` logic with the `useFetch` hook:

```tsx
import React, { useRef, useCallback } from "react";
import Post, { PostProps } from "../post/Post";
import { useGlobalStyles } from "@/common/utils/useGlobalStyles";
import NewPost, { FormErrorsHandle } from "../new-post/NewPostWithCustomFormV4";
import Modal from "@/components/common/modal-overlay/ModalV2";
import JSONDataViewer from "@/components/common/JSONDataViewer";
import { useFetch } from "@/hooks/useFetch";

// Type for Tweet data coming from the API
