  _id: string;
  content: string;
  author: string;
}

const BaseURL = "http://127.0.0.1:3003/tweets/v2";

type PostsListProps = {
  data?: PostProps[];
  isPosting: boolean;
  onStopPosting: () => void;
};

const PostsListV11 = ({ data: initialData = [], isPosting, onStopPosting }: PostsListProps) => {
  const { GLOBAL_APPLICATION_STYLES: { "post-list-container": posts } } = useGlobalStyles();
  const newPostFormErrorsRef = useRef<FormErrorsHandle>(null);

  // Use the useFetch hook for fetching posts
  const { data: fetchedPosts, error, isLoading } = useFetch<TweetData[]>(BaseURL);

  const addPostHandler = useCallback(async (data: PostProps) => {
    const { error, isLoading } = useFetch<TweetData>(BaseURL, {
      method: "POST",
      body: { author: data.author, content: data.body },
    });

    if (error) {
      newPostFormErrorsRef.current?.addApiResponseMessages([error]);
    }

    if (!isLoading) {
      onStopPosting();
    }
  }, [onStopPosting]);

  if (isLoading) {
    return (
      <div style={{ width: "90%", textAlign: "center", color: "white" }}>
        <h2>Loading posts...</h2>
      </div>
    );
  }

  if (error) {
    return (
