        <h2>Error: {error}</h2>
      </div>
    );
  }

  const postsList = fetchedPosts?.map((d) => ({
    id: d._id,
    body: d.content,
    author: d.author,
  })) || initialData;

  return (
    <>
      {isPosting && (
        <Modal onClose={onStopPosting}>
          <NewPost onSubmit={addPostHandler} ref={newPostFormErrorsRef} />
        </Modal>
      )}

      <ul className={posts}>
        {postsList.length > 0 ? (
          postsList.map((p, idx) => <Post key={`id_${p.id}`} author={p.author} body={p.body} />)
        ) : (
          <div style={{ width: "90%", textAlign: "center", color: "white" }}>
            <h2>There are no posts yet</h2>
          </div>
        )}
      </ul>

      <JSONDataViewer metadata={postsList} title="Post Metadata" />
    </>
  );
};

export default PostsListV11;
```

### Key Changes:
