The error you're encountering is caused by calling a hook (`useFetch`) within a `useCallback`, which breaks the [rules of hooks](https://reactjs.org/docs/hooks-rules.html). React hooks must be called at the top level of your component or another hook, not inside functions, conditionals, or loops.

To resolve the issue, you need to separate the logic for making API requests inside the `addPostHandler` and avoid calling the hook inside it.

Here's the corrected version:

### `useFetch` Hook (unchanged):

```ts
import { useState, useEffect } from "react";

interface ApiResponse<T> {
  status: "SUCCESS" | "VALIDATION_ERROR" | "DATABASE_ERROR" | "ERROR";
  messages: string[];
  data: T | null;
  statusCode: number;
  timeStamp: string;
}

type FetchOptions = {
  method?: "GET" | "POST" | "PUT" | "DELETE";
  headers?: Record<string, string>;
  body?: unknown;
};

export const useTweetsAPIFetch = <T,>(url: string, options?: FetchOptions) => {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const response = await fetch(url, {
          method: options?.method || "GET",
          headers: {
            "Content-Type": "application/json",
            ...options?.headers,
          },
          body: options?.body ? JSON.stringify(options.body) : undefined,
        });

        const responseJson: ApiResponse<T> = await response.json();

        if (response.ok && responseJson.status === "SUCCESS") {
          setData(responseJson.data);
        } else {
          setError(responseJson.messages.join(", "));
        }
      } catch (err) {
        setError((err as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [url, options]);

  return { data, error, isLoading };
};
```

### Updated `PostsListV12` Component

The key change here is that you handle the `POST` request directly inside `addPostHandler` rather than using the `useFetch` hook for that part.

```tsx
import React, { useRef, useCallback, useState } from "react";
import Post, { PostProps } from "../post/Post";
