          body: responseJson.data.content,
          author: responseJson.data.author,
        };
        // You may want to update the posts list or handle it as needed
        onStopPosting(); // Close the modal
      } else {
        newPostFormErrorsRef.current?.addApiResponseMessages(responseJson.messages);
        throw new Error(responseJson.messages.join(", "));
      }
    } catch (err) {
      console.error("Error posting data:", (err as Error).message);
    } finally {
      setIsSubmitting(false);
    }
  }, [onStopPosting]);

  if (isLoading) {
    return (
      <div style={{ width: "90%", textAlign: "center", color: "white" }}>
        <h2>Loading posts...</h2>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ width: "90%", textAlign: "center", color: "red" }}>
        <h2>Error: {error}</h2>
      </div>
    );
  }

  const postsList = fetchedPosts?.map((d) => ({
    id: d._id,
    body: d.content,
    author: d.author,
  })) || initialData;

  return (
    <>
      {isPosting && (
        <Modal onClose={onStopPosting}>
          <NewPost onSubmit={addPostHandler} ref={newPostFormErrorsRef} />
        </Modal>
      )}

      <ul className={posts}>
        {postsList.length > 0 ? (
          postsList.map((p, idx) => <Post key={`id_${idx+1}`} author={p.author} body={p.body} />)
        ) : (
          <div style={{ width: "90%", textAlign: "center", color: "white" }}>
            <h2>There are no posts yet</h2>
          </div>
        )}
      </ul>

      <JSONDataViewer metadata={postsList} title="Post Metadata" />
    </>
  );
};

export default PostsListV12;
```

### Changes Made:
1. **No Hook Inside `addPostHandler`**: The `useFetch` hook is only used for fetching the posts on component mount. The `POST` request for adding a post is handled directly using `fetch` inside `addPostHandler`.
2. **State for Submitting**: A new `isSubmitting` state is used to manage the loading state when a new post is being added.
3. **Proper Hook Usage**: React hooks are now only used at the top level of the component.

This will resolve the error and ensure proper hook usage in your component.

To ensure that the `rawStyles` object matches the expected `GlobalStyleProps` type and throw an error if any required field is missing, you can compare the keys of `rawStyles` with the keys defined in the `GlobalStyleProps` type at runtime.

Here’s how you can modify the `getStyles` function to throw an error if any field is missing:

### Updated Code:

```ts
import rawStyles from "../styles/combined-v5.module.css";

export type GlobalStyleProps = {
  "component-selection-section": string;
  main: string;
  header: string;
  img: string;
  ul: string;
  label: string;
  input: string;
  button: string;
  form: string;
  infobox: string;
  "infobox-hint": string;
  "infobox-warning": string;
  "warning--low": string;
  "warning--medium": string;
  "warning--high": string;
  "add-timer": string;
  "blog-posts": string;
  "loading-fallback": string;
  error: string;
  "nav-button": string;
  select: string;
  "info-box": string;
  "info-box-detail": string;
  post: string;
  "post-author": string;
  "post-body": string;
  posts: string;
};

// Function to assert that the rawStyles object matches the GlobalStyleProps type
const getStyles = (): GlobalStyleProps => {
  const requiredFields: Array<keyof GlobalStyleProps> = [
    "component-selection-section",
    "main",
    "header",
    "img",
    "ul",
    "label",
    "input",
    "button",
    "form",
    "infobox",
    "infobox-hint",
    "infobox-warning",
    "warning--low",
    "warning--medium",
    "warning--high",
    "add-timer",
    "blog-posts",
    "loading-fallback",
    "error",
    "nav-button",
    "select",
    "info-box",
    "info-box-detail",
    "post",
    "post-author",
    "post-body",
    "posts",
  ];

  // Check if all required fields exist in rawStyles
  const missingFields = requiredFields.filter((field) => !(field in rawStyles));

  if (missingFields.length > 0) {
    throw new Error(
      `Missing fields in rawStyles: ${missingFields.join(", ")}`
    );
  }

  return rawStyles as GlobalStyleProps;
};

// Hook to return the global styles and the raw styles
export const useGlobalStyles = () => {
  const GLOBAL_APPLICATION_STYLES = getStyles();
  return {
    GLOBAL_APPLICATION_STYLES,
    rawStyles,
  };
};
```

### How It Works:
1. **`requiredFields` Array**: This array contains the keys of the `GlobalStyleProps` type that you expect in `rawStyles`.
2. **`missingFields` Check**: This checks if each required key exists in `rawStyles`. If any key is missing, it's added to the `missingFields` array.
3. **Error Throwing**: If there are missing fields, the function throws an error with a message listing the missing fields.

This approach ensures that you catch any missing properties in your CSS modules at runtime and can prevent issues with styles not being applied due to missing class names.

