To make your `useApiRequest` hook promise-based, you need to use `Promise` with `.then()` and `.catch()` for handling asynchronous operations instead of `async`/`await`. Here's the updated version using promises:

```tsx
import { useState, useCallback } from "react";
import OverlayModal from "@/components/common/central-message-error-overlay/OverlayModal"; // Assuming you saved the modal as OverlayModal

interface ApiResponse<T> {
  status: "SUCCESS" | "VALIDATION_ERROR" | "DATABASE_ERROR" | "ERROR";
  messages: string[];
  data: T | null;
  statusCode: number;
  timeStamp: string;
}

type FetchOptions = {
  method?: "GET" | "POST" | "PUT" | "DELETE";
  headers?: Record<string, string>;
  body?: unknown;
};

export const useApiRequest = <T extends string | number>(
  url: string,
  options?: FetchOptions
) => {
  const [result, setResult] = useState<ApiResponse<T | null> | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const fetchData = useCallback(() => {
    setLoading(true);
    setError(null);

    return fetch(url, {
      method: options?.method || "GET",
      headers: {
        "Content-Type": "application/json",
        ...options?.headers,
      },
      body: options?.body ? JSON.stringify(options.body) : undefined,
    })
      .then((response) => response.json())
      .then((responseJson: ApiResponse<T>) => {
        if (responseJson.status === "SUCCESS") {
          setResult(responseJson);
        } else {
          setError(responseJson.messages.join(", "));
        }
        setLoading(false);
      })
      .catch((err) => {
        setError((err as Error).message);
        setLoading(false);
      });
  }, [url, options]);

  // Inject the overlay modal directly inside the hook
  const overlayModal = <OverlayModal loading={loading} error={error} />;

  return { result, error, loading, fetchData, overlayModal };
};
```

### Changes:
1. **Promise-based approach**: The `fetchData` function now uses `.then()` and `.catch()` to handle the promises from the `fetch` API.
2. **Error handling**: The `.catch()` block captures any errors and sets the error state.

### Usage in a Component:
The hook is now fully promise-based, and you can use it in any component without manually managing the overlay modal or error/loading states:

```tsx
import React, { useEffect } from "react";
import { useApiRequest } from "./useApiRequest";

const BaseURL = "http://127.0.0.1:3003/tweets/v2";

const MyComponent = () => {
  const { result, fetchData, overlayModal } = useApiRequest(BaseURL);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  return (
    <div>
      <h1>MyComponent</h1>

      {/* Overlay modal will automatically render */}
      {overlayModal}

      {result && (
        <p>
          Result: {result.statusCode}, <br />
          Messages: {result.messages.join(", ")}, <br />
          ApiResponse data: {JSON.stringify(result.data)}, <br />
          Type of ApiResponse data: {typeof result.data}
        </p>
      )}
    </div>
  );
};

export default MyComponent;
```

This way, the overlay modal is handled centrally by the hook, and the component only invokes the `fetchData` function when needed.

You can create a TypeScript function that dynamically generates a TypeScript type from a given JSON object. Here's an example of how you could approach this task:

```ts
function generateTypeFromJson(json: Record<string, any>, typeName: string = "GeneratedType"): string {
  let typeDef = `interface ${typeName} {\n`;

  function inferType(value: any): string {
    if (Array.isArray(value)) {
      if (value.length > 0) {
        return `${inferType(value[0])}[]`;
      } else {
        return `any[]`; // If the array is empty, default to `any[]`
      }
    } else if (value === null) {
      return "null";
    } else if (typeof value === "object") {
      return generateTypeFromJson(value);
    } else {
      return typeof value;
    }
  }

  for (const key in json) {
    if (json.hasOwnProperty(key)) {
      const value = json[key];
      typeDef += `  ${key}: ${inferType(value)};\n`;
    }
  }

  typeDef += `}`;

  return typeDef;
}

// Example usage
const sampleJson = {
  id: 1,
  name: "Sample",
  tags: ["typescript", "json"],
  metadata: {
    createdBy: "Admin",
    createdAt: "2024-01-01",
  },
  isActive: true,
};

const generatedType = generateTypeFromJson(sampleJson, "SampleType");
console.log(generatedType);
```

### Explanation:
- **`generateTypeFromJson`**: Takes a JSON object and returns a TypeScript interface as a string.
- **`inferType`**: Infers the type for each value in the JSON.
  - If the value is an array, it recursively infers the type of its elements.
  - If it's an object, it recursively generates a nested type definition.
  - For primitive types (`string`, `number`, `boolean`, etc.), it returns their corresponding TypeScript type.

