type FetchOptions = {
  method?: "GET" | "POST" | "PUT" | "DELETE";
  headers?: Record<string, string>;
  body?: unknown;
};

export const useApiRequest = <T extends string | number>() => {
  // const [result, setResult] = useState<ApiResponse<T | null> | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [showModal, setShowModal] = useState(false);

  const fetchData = useCallback(
    (
      fetchConfigData: { url: string; options?: FetchOptions },
      loadingMessage: string = "Loading...",
      errorMessages: string[] = ["Error occurred"],
      onSuccess: (response: ApiResponse<T>) => void = () => {},
      onFailure: (response: ApiResponse<T>) => void = () => {}
    ) => {
      setLoading(true);
      setError(null);
      toggleVisibility();

      const { url, options } = fetchConfigData;

      return fetch(url, {
        method: options?.method || "GET",
        headers: {
          "Content-Type": "application/json",
          ...options?.headers,
        },
        body: options?.body ? JSON.stringify(options.body) : undefined,
      })
        .then((response) => response.json())
        .then((responseJson: ApiResponse<T>) => {
          if (responseJson.status === "SUCCESS") {
            // setResult(responseJson);
            onSuccess(responseJson);
          } else {
            setError(responseJson.messages.join(", "));
            onFailure(responseJson);
            // toggleVisibility();
          }
        })
        .catch((err) => {
          setError(errorMessages.join(", ") + ": " + (err as Error).message);
          // toggleVisibility();
        })
        .finally(() => {
          setLoading(false);
        });
    },
    []
  );

  const toggleVisibility = () => setShowModal((prev) => !prev);

  // Inject the overlay modal directly inside the hook
  // const overlayModal = <OverlayModal loading={loading} error={error} />;
  const overlayModal = (
    <>
    {showModal && <Modal onClose={toggleVisibility}>
      {loading && <p>Loading...</p>}
      {error && <p style={{ color: "red" }}>Error: {error}</p>}
    </Modal>}
    </>
  );

  return { fetchData, overlayModal };
};

