            // toggleVisibility();
          }
        })
        .catch((err) => {
          // setError(errorMessages.join(", ") + ": " + (err as Error).message);
          setMessages((respMessages) => [
            ...respMessages.concat(
              errorMessages.concat((err as Error).message).map((m) => ({
                messageType: "API Response Error",
                message: m,
              }))
            ),
          ]);
          // toggleVisibility();
        })
        .finally(() => {
          setLoading(false);
        });
    },
    []
  );

  const toggleVisibility = () => setShowModal((prev) => !prev);

  // Inject the overlay modal directly inside the hook
  // const overlayModal = <OverlayModal loading={loading} error={error} />;
  const overlayModal = (
    <>
      {showModal && (
        <Modal onClose={toggleVisibility}>
