      <h2>Loading posts...</h2>
    </div>
  );

  const ErrorMessage = ({ message }: { message: string }) => (
    <div style={{ width: "90%", textAlign: "center", color: "red" }}>
      <h2>Error: {message}</h2>
    </div>
  );

