  id: number;
  name: string;
}

const getData = async () => {
  const data = await fetchGeneric<ApiResponse>('/api/data', {
    method: 'GET',
  });

  console.log(data.id, data.name);
};

const postData = async () => {
  const data = await fetchGeneric<ApiResponse>('/api/data', {
    method: 'POST',
    body: { name: 'New Item' }, // Body will be stringified to JSON
  });

  console.log(data.id, data.name);
};
```

With these changes, you now have a more flexible and properly typed `fetchGeneric` function that works smoothly with both `GET` and `POST` requests (and others) while managing the body content in a way compatible with the `fetch` API.

Here's the completed and improved version of your `useApiRequest` hook, with the flexibility of handling custom success and failure callbacks, as well as custom loading and error messages:

```tsx
import { useState, useCallback } from "react";
import OverlayModal from "@/components/common/central-message-error-overlay/OverlayModal"; // Assuming you saved the modal as OverlayModal

interface ApiResponse<T> {
  status: "SUCCESS" | "VALIDATION_ERROR" | "DATABASE_ERROR" | "ERROR";
  messages: string[];
  data: T | null;
  statusCode: number;
  timeStamp: string;
}

type FetchOptions = {
  method?: "GET" | "POST" | "PUT" | "DELETE";
  headers?: Record<string, string>;
  body?: unknown;
};

export const useApiRequest = <T extends string | number>() => {
  const [result, setResult] = useState<ApiResponse<T | null> | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const fetchData = useCallback(
    (
      fetchConfigData: { url: string; options?: FetchOptions },
      loadingMessage: string = "Loading...",
      errorMessages: string[] = ["Error occurred"],
      onSuccess: (response: ApiResponse<T>) => void = () => {},
      onFailure: (response: ApiResponse<T>) => void = () => {}
    ) => {
      setLoading(true);
      setError(null);

      const { url, options } = fetchConfigData;

      return fetch(url, {
        method: options?.method || "GET",
        headers: {
          "Content-Type": "application/json",
          ...options?.headers,
        },
        body: options?.body ? JSON.stringify(options.body) : undefined,
      })
        .then((response) => response.json())
        .then((responseJson: ApiResponse<T>) => {
          if (responseJson.status === "SUCCESS") {
            setResult(responseJson);
            onSuccess(responseJson);
          } else {
            setError(responseJson.messages.join(", "));
            onFailure(responseJson);
          }
        })
        .catch((err) => {
          setError(errorMessages.join(", ") + ": " + (err as Error).message);
        })
        .finally(() => {
          setLoading(false);
        });
    },
    []
  );

  // Inject the overlay modal directly inside the hook
  const overlayModal = <OverlayModal loading={loading} error={error} />;

  return { result, fetchData, overlayModal };
};
```

### Key Changes:
1. **Custom Callbacks**:
   - `onSuccess`: Invoked when the API call succeeds.
   - `onFailure`: Invoked when the API call fails with a status other than `"SUCCESS"`.

2. **Custom Messages**:
   - `loadingMessage`: A customizable loading message (though it's not used in the overlay yet, you could extend the `OverlayModal` to display it).
   - `errorMessages`: Custom error messages that can be passed to handle different error situations.

3. **Centrally Managed Overlay**:
   The overlay is managed within the hook and automatically handles loading and error states.

### Usage:

Here’s how you can use the hook in a component:

```tsx
import React, { useEffect } from "react";
import { useApiRequest } from "./useApiRequest";

const BaseURL = "http://127.0.0.1:3003/tweets/v2";

const MyComponent = () => {
  const { result, fetchData, overlayModal } = useApiRequest<string>();

  useEffect(() => {
    fetchData(
      { url: BaseURL }, // API configuration
      "Fetching Data...", // Custom loading message
      ["Failed to fetch data"], // Custom error messages
      (response) => {
        console.log("Data fetched successfully:", response.data);
      },
      (response) => {
        console.error("Error fetching data:", response.messages);
      }
    );
  }, [fetchData]);

  return (
    <div>
      <h1>MyComponent</h1>

      {/* Overlay modal will automatically render */}
      {overlayModal}

      {result && (
        <p>
          Result: {result.statusCode}, <br />
          Messages: {result.messages.join(", ")}, <br />
          ApiResponse data: {JSON.stringify(result.data)}, <br />
          Type of ApiResponse data: {typeof result.data}
        </p>
      )}
    </div>
  );
};

export default MyComponent;
```

This makes the hook more reusable, and you can easily manage success and failure scenarios, as well as handle central loading and error messages.

