```tsx
import { useState, useCallback } from "react";
import Modal from "@/components/common/modal-overlay/ModalV2"; // Assuming Modal is saved in the given path

interface ApiResponse<T> {
  status: "SUCCESS" | "VALIDATION_ERROR" | "DATABASE_ERROR" | "ERROR";
  messages: string[];
  data: T | null;
  statusCode: number;
  timeStamp: string;
}

type FetchOptions = {
  method?: "GET" | "POST" | "PUT" | "DELETE";
  headers?: Record<string, string>;
  body?: unknown;
};

export const useApiRequest = <T extends string | number>() => {
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [showModal, setShowModal] = useState(false);

  const toggleVisibility = () => setShowModal((prev) => !prev);

  const fetchData = useCallback(
    (
      { url, options }: { url: string; options?: FetchOptions },
      onSuccess: (response: ApiResponse<T>) => void = () => {},
      onFailure: (response: ApiResponse<T>) => void = () => {},
      errorMessages: string[] = ["An error occurred"]
    ) => {
      setLoading(true);
      setError(null);
      toggleVisibility();

      fetch(url, {
        method: options?.method || "GET",
        headers: {
          "Content-Type": "application/json",
          ...options?.headers,
        },
        body: options?.body ? JSON.stringify(options.body) : undefined,
      })
        .then((response) => response.json())
        .then((responseJson: ApiResponse<T>) => {
          if (responseJson.status === "SUCCESS") {
            onSuccess(responseJson);
          } else {
            setError(responseJson.messages.join(", "));
            onFailure(responseJson);
          }
        })
        .catch((err) => {
          setError(errorMessages.join(", ") + ": " + (err as Error).message);
        })
        .finally(() => {
          setLoading(false);
        });
    },
    []
  );

  const overlayModal = (
    <>
      {showModal && (
        <Modal onClose={toggleVisibility}>
          {loading && <p>Loading...</p>}
          {error && <p style={{ color: "red" }}>Error: {error}</p>}
        </Modal>
      )}
    </>
  );

  return { fetchData, overlayModal };
};
```

### Changes and Simplification:

1. **Removed Unnecessary Parameters**: 
   - `loadingMessage` was removed because you already handle loading within the modal. 
   - The hook automatically manages error messages and loading states.

2. **Simplified Modal Logic**:
   - The modal displays loading and error messages centrally. When `loading` or `error` states change, the modal visibility is toggled automatically.

3. **Callback Functions**: 
   - You can still pass success (`onSuccess`) and failure (`onFailure`) callbacks to handle the response when needed.

### Example Usage:

```tsx
