const MyComponent = () => {
  const { fetchData, overlayModal } = useApiRequest<string>();

  const handleFetchData = () => {
    fetchData(
      { url: "http://example.com/api" },
      (response) => {
        console.log("Success:", response.data);
      },
      (response) => {
        console.error("Failure:", response.messages);
      }
    );
  };

  return (
    <div>
      <h1>My Component</h1>
      <button onClick={handleFetchData}>Fetch Data</button>

      {/* The modal is centrally managed and displayed by the hook */}
