Yes, we can make the `fetchData` function generic rather than the entire hook so that the same `useApiRequest` hook can handle multiple URLs and data types dynamically.

The idea is to keep the hook logic simple and make `fetchData` flexible to handle multiple URLs and response types. Here’s how you can modify it:

### Updated Hook: `useApiRequest`

```typescript
import { useState, useCallback } from "react";

interface ApiResponse<T> {
  status: "SUCCESS" | "VALIDATION_ERROR" | "DATABASE_ERROR" | "ERROR";
  messages: string[];
  data: T | null;
  statusCode: number;
  timeStamp: string;
}

type FetchOptions = {
  method?: "GET" | "POST" | "PUT" | "DELETE";
  headers?: Record<string, string>;
  body?: unknown;
};

export const useApiRequest = () => {
  const [result, setResult] = useState<ApiResponse<any> | null>(null); // Generic result
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  // Generic fetchData function for dynamic URLs and data types
  const fetchData = useCallback(
    async <T>(url: string, options?: FetchOptions): Promise<void> => {
      setLoading(true);
      setError(null);

      try {
        const response = await fetch(url, {
          method: options?.method || "GET",
          headers: {
            "Content-Type": "application/json",
            ...options?.headers,
          },
          body: options?.body ? JSON.stringify(options.body) : undefined,
        });

        const responseJson: ApiResponse<T> = await response.json();

        if (response.ok && responseJson.status === "SUCCESS") {
          setResult(responseJson);
        } else {
          setError(responseJson.messages.join(", "));
        }
      } catch (err) {
        setError((err as Error).message);
      } finally {
        setLoading(false);
      }
    },
    []
  );

  return { result, error, loading, fetchData };
};
```

