                               localIdentName: '[name]__[local]--[hash:base64:5]', // Custom naming
                           },
                       },
                   },
               ],
           },
       ],
   },
   ```

2. **Import Your CSS**: Import your CSS file in your component, and the styles will be scoped locally with generated names:

   ```javascript
   import styles from './styles/styles.css';

   const MyComponent = () => {
       return (
           <div className={styles.myClass}>
               Hello, World!
           </div>
       );
   };
   ```

