    return arr.sort((a, b) => {
        if (a[field] < b[field]) return ascending ? -1 : 1;
        if (a[field] > b[field]) return ascending ? 1 : -1;
        return 0;
    });
};

// Example usage:
const sortedByAge = sortArrayByField(people, 'age');
console.log('Sorted by Age:', sortedByAge);

const sortedByNameDescending = sortArrayByField(people, 'name', false);
console.log('Sorted by Name Descending:', sortedByNameDescending);
```

### Explanation:
- **Interface `Person`:** Defines the structure of the objects in the array.
- **`people` array:** Contains five objects with the fields `id`, `name`, `age`, `gender`, and `country`.
- **`sortArrayByField` function:**
  - It takes three parameters: an array, a field to sort by, and an optional flag (`ascending`, default is `true`).
  - It uses `Array.sort` to compare the field values and sort them accordingly.

You can sort the array by any field like `name`, `age`, `gender`, etc.

Here are some TypeScript examples of DOM manipulation in a type-safe way:

### 1. **Selecting Elements**
When selecting elements from the DOM, you want to make sure TypeScript knows what type of element you're working with.

```typescript
// Select an element by ID and safely cast it as an HTMLInputElement
const inputElement = document.getElementById('myInput') as HTMLInputElement;

if (inputElement) {
  inputElement.value = 'Type-safe DOM manipulation!';
}
```

### 2. **Creating and Appending Elements**
When creating new elements, you can use TypeScript to make sure you're manipulating the right type of element.

```typescript
// Create a new div element with specific types
const newDiv: HTMLDivElement = document.createElement('div');
newDiv.id = 'newDiv';
newDiv.textContent = 'Hello, this is a new div!';

// Append it to the body
document.body.appendChild(newDiv);
```

### 3. **Adding Event Listeners with Type Safety**
You can make sure TypeScript knows exactly what type of event listener you're adding, and that you're working with the correct event type.

```typescript
const button = document.getElementById('myButton') as HTMLButtonElement;

if (button) {
  button.addEventListener('click', (event: MouseEvent) => {
    console.log('Button clicked!');
  });
}
```

### 4. **Updating CSS Styles in a Type-Safe Way**
When updating the styles of an element, TypeScript ensures that only valid CSS properties are used.

```typescript
const divElement = document.getElementById('styledDiv') as HTMLDivElement;

if (divElement) {
  divElement.style.backgroundColor = 'lightblue';
  divElement.style.width = '200px';
  divElement.style.height = '100px';
}
```

### 5. **Manipulating Input Elements**
You can safely manipulate form fields like `<input>`, `<textarea>`, etc., ensuring type safety.

```typescript
