if (inputField) {
  inputField.value = 'John Doe';
  console.log(inputField.value); // Outputs: John Doe
}
```

### 6. **Handling Form Submission**
You can also handle forms and their input values in a type-safe way.

```typescript
const form = document.getElementById('myForm') as HTMLFormElement;

if (form) {
  form.addEventListener('submit', (event: Event) => {
    event.preventDefault();
    const formData = new FormData(form);
    console.log(formData.get('username'));
  });
}
```

### 7. **Using Query Selector with Type Assertions**
For more flexible selections, `querySelector` can be used with type assertions to specify the expected element type.

```typescript
