import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;
import com.example.repository.UserRepository;
import com.example.model.User;
import com.example.exception.UserNotFoundException;
import com.example.exception.UserAlreadyExistsException;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;

import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;

@Service
public class UserService {

    @Autowired
    private UserRepository userRepository;

    @Autowired
    private BCryptPasswordEncoder passwordEncoder;

    private static final String SECRET_KEY = "your-secret-key";

    public String registerUser(User userData) throws UserAlreadyExistsException {
        String username = userData.getUsername();
        String password = userData.getPassword();

        Optional<User> existingUser = userRepository.findByUsername(username);
        if (existingUser.isPresent()) {
            throw new UserAlreadyExistsException("Username is already taken.");
        }

        String hashedPassword = passwordEncoder.encode(password);

        User newUser = new User();
        newUser.setUsername(username);
        newUser.setPassword(hashedPassword);
        newUser.setName(userData.getName());
        newUser.setEmail(userData.getEmail());
        newUser.setMobileNumber(userData.getMobileNumber());
        newUser.setRole("user");

        userRepository.save(newUser);

        return generateToken(newUser);
    }

    public String loginUser(String username, String password) throws Exception {
        Optional<User> user = userRepository.findByUsername(username);
        if (user.isEmpty() || !passwordEncoder.matches(password, user.get().getPassword())) {
            throw new Exception("Invalid username or password");
        }

        return generateToken(user.get());
    }

    public List<User> getAllUsers() {
        return userRepository.findAll()
                .stream()
                .map(user -> {
                    user.setPassword(null); // Exclude password
                    return user;
                })
                .collect(Collectors.toList());
    }

    public User updateUserRole(String userId) throws UserNotFoundException {
        User user = userRepository.findById(userId)
                .orElseThrow(() -> new UserNotFoundException("User not found"));

        user.setRole("admin");
        return userRepository.save(user);
    }

    public User getUserById(String userId) throws UserNotFoundException {
        User user = userRepository.findById(userId)
                .orElseThrow(() -> new UserNotFoundException("User not found"));
        user.setPassword(null); // Exclude password
        return user;
    }

    public User updateUserById(String userId, User updatedData) throws UserNotFoundException {
        User user = userRepository.findById(userId)
                .orElseThrow(() -> new UserNotFoundException("User not found"));

        user.setUsername(Optional.ofNullable(updatedData.getUsername()).orElse(user.getUsername()));
        user.setName(Optional.ofNullable(updatedData.getName()).orElse(user.getName()));
        user.setEmail(Optional.ofNullable(updatedData.getEmail()).orElse(user.getEmail()));
        user.setMobileNumber(Optional.ofNullable(updatedData.getMobileNumber()).orElse(user.getMobileNumber()));

        return userRepository.save(user);
    }

    private String generateToken(User user) {
        return Jwts.builder()
                .setSubject(user.getId())
                .claim("userId", user.getId())
                .claim("userName", user.getName())
                .signWith(SignatureAlgorithm.HS512, SECRET_KEY)
                .compact();
    }
}
```

### Explanation:
- **BCryptPasswordEncoder**: Used to hash passwords.
- **JWT**: Uses `io.jsonwebtoken.Jwts` to generate a JWT token.
- **UserRepository**: A repository interface for MongoDB.
- **Exceptions**: Custom exceptions like `UserNotFoundException` and `UserAlreadyExistsException`.

