### `TreeStructureGenerator.java`

```java
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class TreeStructureGenerator {

    public static Map<String, Object> generateTreeStructure(List<Object> inputArray) {
        if (inputArray == null || inputArray.isEmpty()) {
            return Map.of(
                    "isValid", ArrayValidationMessageCodes.VALID_ARRAY.isValid(),
                    "errorType", ArrayValidationMessageCodes.VALID_ARRAY.getErrorType(),
                    "message", ArrayValidationMessageCodes.VALID_ARRAY.getMessage(),
                    "code", ArrayValidationMessageCodes.VALID_ARRAY.getCode(),
                    "treeStructure", new ArrayList<TreeNode>()
            );
        }

        List<TreeNode> treeStructure = new ArrayList<>();
        for (Object element : inputArray) {
            if (element instanceof String) {
                treeStructure.add(new TreeNode((String) element));
            } else if (element instanceof List) {
                List<?> nestedArray = (List<?>) element;
                if (nestedArray.size() == 1 && nestedArray.get(0) instanceof String) {
                    treeStructure.add(new TreeNode((String) nestedArray.get(0)));
                } else if (nestedArray.size() == 2 && nestedArray.get(0) instanceof String && nestedArray.get(1) instanceof List) {
                    TreeNode parent = new TreeNode((String) nestedArray.get(0));
                    List<?> children = (List<?>) nestedArray.get(1);
                    for (Object child : children) {
                        if (child instanceof String) {
                            parent.addChild(new TreeNode((String) child));
                        } else {
                            return Map.of(
                                    "isValid", ArrayValidationMessageCodes.INVALID_STRUCTURE.isValid(),
                                    "errorType", ArrayValidationMessageCodes.INVALID_STRUCTURE.getErrorType(),
                                    "message", ArrayValidationMessageCodes.INVALID_STRUCTURE.getMessage(),
                                    "code", ArrayValidationMessageCodes.INVALID_STRUCTURE.getCode()
                            );
                        }
                    }
                    treeStructure.add(parent);
                } else {
                    return Map.of(
                            "isValid", ArrayValidationMessageCodes.INVALID_STRUCTURE.isValid(),
                            "errorType", ArrayValidationMessageCodes.INVALID_STRUCTURE.getErrorType(),
                            "message", ArrayValidationMessageCodes.INVALID_STRUCTURE.getMessage(),
                            "code", ArrayValidationMessageCodes.INVALID_STRUCTURE.getCode()
                    );
                }
            } else {
                return Map.of(
                        "isValid", ArrayValidationMessageCodes.INVALID_STRUCTURE.isValid(),
                        "errorType", ArrayValidationMessageCodes.INVALID_STRUCTURE.getErrorType(),
                        "message", ArrayValidationMessageCodes.INVALID_STRUCTURE.getMessage(),
                        "code", ArrayValidationMessageCodes.INVALID_STRUCTURE.getCode()
                );
            }
        }

        return Map.of(
                "isValid", ArrayValidationMessageCodes.VALID_ARRAY.isValid(),
                "errorType", ArrayValidationMessageCodes.VALID_ARRAY.getErrorType(),
                "message", ArrayValidationMessageCodes.VALID_ARRAY.getMessage(),
                "code", ArrayValidationMessageCodes.VALID_ARRAY.getCode(),
                "treeStructure", treeStructure
        );
    }
}
