import React, { createContext, useContext, useMemo, useState } from "react";
import {
    addLevelAndParentIdField,
    filterByValueForGivenField,
    flattenTreeData,
    getDistinctParentIds,
    getDistinctValueForGivenField,
} from "../../common/utils/array-operation-utils";

// Function to add showChildren field to each node in the tree
function addShowChildrenField(treeData) {
    function traverseAndAddField(node) {
        node.showChildren = false;

        if (node.children && node.children.length > 0) {
            node.children.forEach(child => traverseAndAddField(child));
        }
    }

    treeData.forEach(rootNode => traverseAndAddField(rootNode));
    return treeData;
}

// Function to update the showChildren field of a specific node by uniqueID
function updateShowChildrenById(treeData, uniqueID, showChildrenValue) {
    function traverseAndUpdate(node) {
        if (node.uniqueID === uniqueID) {
            node.showChildren = showChildrenValue;
            return true;
        }

        if (node.children && node.children.length > 0) {
            for (let child of node.children) {
                if (traverseAndUpdate(child)) {
                    return true;
                }
            }
        }

        return false;
    }

    treeData.forEach(rootNode => traverseAndUpdate(rootNode));
    return treeData;
}

// Initial shared data
const initialSharedData = {
    showMetaData: false,
    styles: {
        levelItemStyle: {
            display: "flex",
            justifyContent: "space-between",
            gap: "5px",
        },
        nodeChildrenItemStyle: {
            marginBottom: "50px",
            display: "flex",
            justifyContent: "space-between",
        },
        nodeItemStyle: {
            padding: "10px",
            border: "1px solid red",
            fontSize: "10px",
        },
        configurationAndMetadataItemStyle: {
            padding: "10px",
            border: "10px solid green",
            fontSize: "10px",
            flex: "1",
        },
    },
    dataWithLevelAndParentIdField: [], // Initialize with an empty array
};

// Create a context for shared configurations and data
const SharedConfigurationsContext = createContext();

// Create a provider component
const SharedConfigurationsProvider = ({ children, data }) => {
    const [sharedData, setSharedData] = useState({
        ...initialSharedData,
        dataWithLevelAndParentIdField: addLevelAndParentIdField(
            addShowChildrenField(data)
        ),
    });

    const toggleShowMetaData = () => {
        setSharedData((prev) => ({ ...prev, showMetaData: !prev.showMetaData }));
    };

    const toggleShowChildrenForId = (uniqueID) => {
        setSharedData((prev) => ({
            ...prev,
            dataWithLevelAndParentIdField: updateShowChildrenById(
                prev.dataWithLevelAndParentIdField,
                uniqueID,
                !prev.dataWithLevelAndParentIdField.find(node => node.uniqueID === uniqueID)?.showChildren
            ),
        }));
    };

    const flattenedData = useMemo(
        () => flattenTreeData(sharedData.dataWithLevelAndParentIdField),
        [sharedData.dataWithLevelAndParentIdField]
    );

    const levelCompArr = useMemo(() => {
        const distinctLevels = getDistinctValueForGivenField(flattenedData,'level');
        return distinctLevels.map((level) => ({
            level,
            levelData:
                filterByValueForGivenField(flattenedData, level, "level") || [],
        }));
    }, [flattenedData]);

    const getNodeChildrenCompArr = (levelData) => {
        const distinctParentIds = getDistinctParentIds(levelData);
        return distinctParentIds.map((parentId) => ({
            parentId,
            nodeChildrenData:
                filterByValueForGivenField(levelData, parentId, "parentId") || [],
        }));
    };

    return (
        <SharedConfigurationsContext.Provider
            value={{
                sharedData,
                toggleShowMetaData,
                toggleShowChildrenForId,
                levelCompArr,
                getNodeChildrenCompArr,
            }}
        >
            {children}
        </SharedConfigurationsContext.Provider>
    );
};

// Custom hook to use shared configurations and data
const useSharedConfigurations = () => useContext(SharedConfigurationsContext);

export { useSharedConfigurations, SharedConfigurationsProvider };
