To render the tree data with collapsible nodes, you can use a React component that allows expanding and collapsing of tree nodes. Here’s how you can implement this using a functional component with state management:

```javascript
import React, { useState } from 'react';

const generateTreeData = (depth, itemsPerLevel) => {
  const data = [];
  let uniqueId = 1;

  const generateChildren = (parentId, currentDepth) => {
    if (currentDepth >= depth) return;

    for (let i = 0; i < itemsPerLevel; i++) {
      const id = uniqueId++;
      const node = {
        uniqueId: id,
        name: `Item ${id}`,
        children: [],
        parentId: parentId
      };

      data.push(node);
      generateChildren(id, currentDepth + 1);
    }
  };

  generateChildren(0, 0);

  data.forEach(item => {
    if (item.parentId !== 0) {
      const parent = data.find(parent => parent.uniqueId === item.parentId);
      parent.children.push(item);
    }
  });

  return data;
};

const DisplayData = ({ treeData }) => {
  const [openNodes, setOpenNodes] = useState(new Set());

  const toggleNode = (id) => {
    setOpenNodes(prevOpenNodes => {
      const newOpenNodes = new Set(prevOpenNodes);
      if (newOpenNodes.has(id)) {
        newOpenNodes.delete(id);
      } else {
        newOpenNodes.add(id);
      }
      return newOpenNodes;
    });
  };

  const renderNode = (node) => {
    const hasChildren = node.children.length > 0;
    const isOpen = openNodes.has(node.uniqueId);

    return (
      <div key={node.uniqueId}>
        <div style={{ marginLeft: '20px' }}>
          {hasChildren && (
            <button onClick={() => toggleNode(node.uniqueId)}>
              {isOpen ? '-' : '+'}
            </button>
          )}
          {node.name}
        </div>
        {isOpen && node.children.map(renderNode)}
      </div>
    );
  };

  return (
    <div>
      {treeData.filter(node => node.parentId === 0).map(renderNode)}
    </div>
  );
};

// Generate tree with depth 7 and 3 items at each level
const treeData = generateTreeData(7, 3);

const App = () => {
  return (
    <div>
      <h1>Tree Data</h1>
      <DisplayData treeData={treeData} />
    </div>
  );
}

export default App;
```

