```javascript
import React, { useEffect, useState } from 'react';

const RadioButtonsComponent = ({
    initialSelectedOption = '',
    options = [],
    onChange = () => {},
    containerStyle = {},
    labelStyle = {},
    selectedOptionStyle = {},
    showSelectedOptionInfo = false
}) => {
