                    <ArcherRow style={styles.rowStyle}>
                        {archerBoxes
                            .filter(box => box.id !== updatedFirstElement.uniqueId)
                            .map(box => (
                                <ArcherBoxComponent
                                    key={box.id}
                                    id={box.id}
                                    label={box.label}
                                    style={box.style}
                                />
                            ))}
