        const updatedNode = { ...node, level: currentLevel, parentId, showChildren: false };

        if (updatedNode.children) {
            updatedNode.children = addLevelAndParentIdField(
                updatedNode.children,
                currentLevel + 1,
                updatedNode.uniqueID
            );
        }

