    const result = [];

    const flatten = (node) => {
        result.push({ ...node });
        if (node.children) {
            node.children.forEach((child) => flatten(child));
        }
    };

    nodes.forEach((node) => flatten(node));

    return result;
};

// Function to filter nodes by level
