    return data.filter((node) => node.level === level);
};

// Function to filter nodes by a specific field value
const filterByValueForGivenField = (data, value, fieldName = "level") => {
    return data.filter((node) => node[fieldName] === value);
};

// Function to get distinct parent IDs
const getDistinctParentIds = (flattenedData) => {
    const parentIds = flattenedData.map((node) => node.parentId);
    return [...new Set(parentIds)].sort((a, b) => a - b);
};

// Function to get distinct values for a specific field
const getDistinctValueForGivenField = (
    flattenedData,
    fieldName = "parentId"
) => {
    const values = flattenedData.map((node) => node[fieldName]);
    return [...new Set(values)].sort((a, b) => a - b);
};

// Function to update showChildren for a node by uniqueID
