Here's how you can refactor the code by creating an enum for error codes and using it in the `isValidTreeData` method:

```javascript
// Error codes enum
const TreeValidationErrorCodes = {
    INVALID_INPUT: "INVALID_INPUT",
    MISSING_FIELDS: "MISSING_FIELDS",
    CYCLIC_DEPENDENCY: "CYCLIC_DEPENDENCY",
    DUPLICATE_UNIQUE_ID: "DUPLICATE_UNIQUE_ID",
    VALID_TREE: "VALID_TREE"
};

/**
 * Checks if a node has children.
 * @param {Object} node - The node to check.
 * @returns {boolean} - True if the node has children, false otherwise.
 */
const hasChildren = (node) => node.children && node.children.length > 0;

/**
 * Validates the tree data against multiple conditions.
 * @param {Array} nodes - The nodes to validate.
 * @returns {Object} - An object containing `isValid` (boolean) and `code` (string).
 */
const isValidTreeData = (nodes = []) => {
    if (!Array.isArray(nodes)) {
        return { isValid: false, code: TreeValidationErrorCodes.INVALID_INPUT };
    }

    const seenIds = new Set();
    const checkNode = (node, visited = new Set()) => {
        if (!node.name || !node.parentId || !node.uniqueId) {
            return { isValid: false, code: TreeValidationErrorCodes.MISSING_FIELDS };
        }
        if (visited.has(node.uniqueId)) {
            return { isValid: false, code: TreeValidationErrorCodes.CYCLIC_DEPENDENCY };
        }
        if (seenIds.has(node.uniqueId)) {
            return { isValid: false, code: TreeValidationErrorCodes.DUPLICATE_UNIQUE_ID };
        }
        seenIds.add(node.uniqueId);
        visited.add(node.uniqueId);
        if (hasChildren(node)) {
            for (const child of node.children) {
                const result = checkNode(child, new Set(visited));
                if (!result.isValid) {
                    return result;
                }
            }
        }
        return { isValid: true, code: TreeValidationErrorCodes.VALID_TREE };
    };

    for (const node of nodes) {
        const result = checkNode(node);
        if (!result.isValid) {
            return result;
        }
    }

    return { isValid: true, code: TreeValidationErrorCodes.VALID_TREE };
};

export { isValidTreeData, TreeValidationErrorCodes };
```

### Explanation:
- **TreeValidationErrorCodes:** This is an enum-like object that stores the error codes.
- **isValidTreeData:** The function now returns `code` instead of `message`. This `code` corresponds to one of the values in `TreeValidationErrorCodes`.

