                        margin: "20px 5px",
                    }}
                >
                    {error ? (
                        <p style={{ color: "red" }}>Error: {error}</p>
                    ) : (
                        <pre>{JSON.stringify(metadata, null, 2)}</pre>
                    )}
                </div>
            )}
        </div>
    );
};

const processStep = (stepTitle, stepData, simulateError = false) => {
    return new Promise((resolve, reject) => {
        // Simulate asynchronous processing with setTimeout
        setTimeout(() => {
            if (simulateError) {
                reject(`Error occurred in step: ${stepTitle}`);
            } else {
                resolve({ title: stepTitle, metadata: stepData });
            }
        }, 1000);
    });
};

const processTreeDataWithPromises = (data) => {
    const steps = [];

    return processStep("Get Raw tree data", data)
        .then((step) => {
            steps.push(step);
            const withExtraFields = addLevelAndParentIdFields(data);
            return processStep("Add level and parentId fields", withExtraFields);
        })
        .then((step) => {
            steps.push(step);
            const flattenedData = flattenTreeData(step.metadata);
            return processStep("Get Flatten array", flattenedData);
        })
        .then((step) => {
            steps.push(step);
            const levels = [...new Set(step.metadata.map((item) => item.level))];
            return processStep("Get All distinct levels", levels);
        })
        .then((step) => {
            steps.push(step);
            const parentIdsByLevel = getDistinctValuesForField(step.metadata, "parentId");
            return processStep("Get All distinct parent ids for each level", parentIdsByLevel);
        })
        .then((step) => {
            steps.push(step);
            const levelSections = createLevelSections(data, parentIdsByLevel);
            return processStep("Create levelSection data", levelSections);
        })
        .then((step) => {
            steps.push(step);
            return steps; // Final processed steps data
        })
        .catch((error) => {
            steps.push({ title: "Error", metadata: null, error });
            return steps; // Return steps with error included
        });
};

const TransformTreeDataGroupByLevelAndParentId = ({ data = [] }) => {
    const [newTreeData, setNewTreeData] = useState([]);
    const [stepDataArr, setStepDataArr] = useState([]);

    useEffect(() => {
        if (!data || data.length === 0) return;

        processTreeDataWithPromises(data).then((steps) => {
            setStepDataArr(steps);

            // If no error, set the final processed data
            if (!steps.some(step => step.error)) {
                setNewTreeData(steps[steps.length - 1].metadata);
            }
        });
    }, [data]);

    return (
        <>
            <h1>
                Transform given tree data into a new array, containing objects of level.
                Each level object will contain sections. Each section will contain
                nodes.
            </h1>

            <h2>Step Details:-</h2>
            {stepDataArr.map(({ title, metadata, error }, index) => (
                <JSONDataViewer
                    key={index}
                    step={index + 1}
                    title={title}
                    metadata={metadata}
                    error={error}
                />
            ))}

            <h2>Final Outcome:-</h2>
            {!stepDataArr.some(step => step.error) && (
                <JSONDataViewer
                    title={"Final Data"}
                    metadata={newTreeData}
                    initialValueToShowMetadata={true}
                />
            )}
        </>
    );
};

export default TransformTreeDataGroupByLevelAndParentId;
```

### Key Changes:

1. **`error` Prop in `JSONDataViewer`**:
   - Added an `error` prop to display error messages in case a step fails. The error message is displayed in red.

2. **Error Handling in `processStep`**:
   - Each step can now simulate an error using the `simulateError` parameter. When an error occurs, the promise is rejected, triggering the `.catch` block.

3. **Error Handling in `processTreeDataWithPromises`**:
   - If an error occurs at any step, it is caught in the `.catch` block, and a step with an error message is added to the steps array. The processing stops, and the final state reflects the error.

4. **Conditional Rendering Based on Errors**:
   - In the final rendering of the component, the final outcome is only shown if no errors are detected. Otherwise, the error is displayed in the steps list.

### Usage:

