```javascript
// Error codes enum
const TreeValidationErrorCodes = {
    INVALID_INPUT: {
        errorType: "non-recoverable",
        message: "Input should be an array of objects.",
        code: "INVALID_INPUT"
    },
    MISSING_FIELDS: {
        errorType: "non-recoverable",
        message: "Each object must have 'name', 'parentId', and 'uniqueId' fields.",
        code: "MISSING_FIELDS"
    },
    CYCLIC_DEPENDENCY: {
        errorType: "non-recoverable",
        message: "Cyclic dependency detected.",
        code: "CYCLIC_DEPENDENCY"
    },
    DUPLICATE_UNIQUE_ID: {
        errorType: "recoverable",
        message: "Duplicate uniqueId found.",
        code: "DUPLICATE_UNIQUE_ID"
    },
    VALID_TREE: {
        errorType: "recoverable",
        message: "Tree data is valid.",
        code: "VALID_TREE"
    }
};

/**
 * Checks if a node has children.
 * @param {Object} node - The node to check.
 * @returns {boolean} - True if the node has children, false otherwise.
 */
const hasChildren = (node) => node.children && node.children.length > 0;

/**
 * Validates the tree data against multiple conditions.
 * @param {Array} nodes - The nodes to validate.
 * @returns {Object} - An object containing `isValid` (boolean), `errorType` (string), and `code` (string).
 */
const isValidTreeData = (nodes = []) => {
    if (!Array.isArray(nodes)) {
        return { isValid: false, ...TreeValidationErrorCodes.INVALID_INPUT };
    }

    const seenIds = new Set();
    const checkNode = (node, visited = new Set()) => {
        if (!node.name || !node.parentId || !node.uniqueId) {
            return { isValid: false, ...TreeValidationErrorCodes.MISSING_FIELDS };
        }
        if (visited.has(node.uniqueId)) {
            return { isValid: false, ...TreeValidationErrorCodes.CYCLIC_DEPENDENCY };
        }
        if (seenIds.has(node.uniqueId)) {
            return { isValid: false, ...TreeValidationErrorCodes.DUPLICATE_UNIQUE_ID };
        }
        seenIds.add(node.uniqueId);
        visited.add(node.uniqueId);
        if (hasChildren(node)) {
            for (const child of node.children) {
                const result = checkNode(child, new Set(visited));
                if (!result.isValid) {
                    return result;
                }
            }
        }
        return { isValid: true, ...TreeValidationErrorCodes.VALID_TREE };
    };

    for (const node of nodes) {
        const result = checkNode(node);
        if (!result.isValid) {
            return result;
        }
    }

    return { isValid: true, ...TreeValidationErrorCodes.VALID_TREE };
};

export { isValidTreeData, TreeValidationErrorCodes };
```

### Explanation:
- **TreeValidationErrorCodes:** Each error code now contains three fields:
  - `errorType`: Indicates whether the error is recoverable or non-recoverable.
  - `message`: The error message associated with the validation error.
  - `code`: A unique code representing the error.
- **isValidTreeData:** The function returns an object that includes `isValid`, `errorType`, `message`, and `code` based on the validation result.

This structure provides more detailed information about validation errors and makes the handling of different error types more flexible.

