### Updated `ArrowConnector.js`

```javascript
import React, { useLayoutEffect, useState } from 'react';

const ArrowConnector = ({ startId, endId }) => {
  const [arrowStyle, setArrowStyle] = useState({});

  useLayoutEffect(() => {
    const updateArrowPosition = () => {
      const startElement = document.getElementById(startId);
      const endElement = document.getElementById(endId);

      if (startElement && endElement) {
        const startRect = startElement.getBoundingClientRect();
        const endRect = endElement.getBoundingClientRect();

        // Calculate the starting point at the right middle of startDiv
        const startX = startRect.right;
        const startY = startRect.top + startRect.height / 2;

        // Calculate the ending point at the left middle of endDiv
        const endX = endRect.left;
        const endY = endRect.top + endRect.height / 2;

        setArrowStyle({
          position: 'absolute',
          left: `${startX}px`,
          top: `${startY}px`,
          width: `${Math.sqrt((endX - startX) ** 2 + (endY - startY) ** 2)}px`,
          transform: `rotate(${Math.atan2(endY - startY, endX - startX) * (180 / Math.PI)}deg)`,
          transformOrigin: '0 0',
          borderTop: '2px solid black',
        });
      }
    };

    updateArrowPosition();
    window.addEventListener('resize', updateArrowPosition);

    return () => {
      window.removeEventListener('resize', updateArrowPosition);
    };
  }, [startId, endId]);

  return <div style={arrowStyle}></div>;
};

const ArrowConnectorExample = () => {
  return (
    <div style={{ position: 'relative', display: 'flex', alignItems: 'center', padding: '50px' }}>
      <div id="startDiv" style={{ width: '100px', height: '100px', background: 'red', marginRight: '50px' }}>Start</div>
      <div id="endDiv" style={{ width: '100px', height: '100px', background: 'blue', marginLeft: '50px' }}>End</div>
      <ArrowConnector startId="startDiv" endId="endDiv" />
    </div>
  );
};

export default ArrowConnectorExample;
export { ArrowConnector };
```

### Explanation:

1. **Arrow Positioning**:
   - **Start Point**: The arrow starts from the right middle (`startX = startRect.right; startY = startRect.top + startRect.height / 2`).
   - **End Point**: The arrow ends at the left middle (`endX = endRect.left; endY = endRect.top + endRect.height / 2`).

2. **Flexbox Layout**:
   - The container is set to `display: flex` and `alignItems: center` to align `startDiv` and `endDiv` horizontally in the center.
   - `marginRight` and `marginLeft` are used to space the divs apart.

3. **Arrow Styling**:
   - The arrow is dynamically positioned and rotated to connect the right middle of `startDiv` to the left middle of `endDiv`.

This setup will create a layout where `startDiv` and `endDiv` are aligned in a row, with an arrow connecting them from the right middle of `startDiv` to the left middle of `endDiv`. The arrow adjusts dynamically if the window is resized.

