const addLevelField = (nodes, currentLevel = 0) => {
    return nodes.map(node => {
        const updatedNode = { ...node, level: currentLevel };

        if (updatedNode.children) {
            updatedNode.children = addLevelField(updatedNode.children, currentLevel + 1);
        }

        return updatedNode;
    });
};

