import {
    nameArr,
    mughalDynasty,
    ambaniFamily,
    britishRoyalFamily,
    designPatternsTreeData,
    continentData,
    treeDataProcessAndDisplayWithReactArcherSteps,
    programmingLanguagesTreeData,
} from './constants'



let currentId = 1;

const addIds = (node, overrideId=false) => {
    // Create a copy of the node
    const updatedNode = { ...node };

    // Check if the node already has a non-null, non-empty uniqueId
    if (overrideId || !updatedNode.uniqueId || updatedNode.uniqueId.trim() === "") {
        // Assign an ID to the current node if uniqueId is missing or empty
        updatedNode.uniqueId = `NODE_ID_${currentId++}`;
    }

    // If there are children, recursively assign IDs to them
    if (updatedNode.children) {
        updatedNode.children = updatedNode.children.map((child) => addIds(child));
    }

    return updatedNode;
};

const ARRAY_TYPE = {
    nameArr: "nameArr",
    mughalDynasty: "mughalDynasty",
    ambaniFamily: "ambaniFamily",
    britishRoyalFamily: "britishRoyalFamily",
    designPatternsTreeData: "designPatternsTreeData",
    continentData:"continentData",
    treeDataProcessAndDisplayWithReactArcherSteps:"treeDataProcessAndDisplayWithReactArcherSteps",
    programmingLanguagesTreeData:"programmingLanguagesTreeData"
};
const getUpdatedNameArrForType = (type = null) => {
    if (!type) return [];
    switch (type) {
        case ARRAY_TYPE.nameArr:
            return nameArr.map((n) => addIds(n));
        case ARRAY_TYPE.mughalDynasty:
            return mughalDynasty.map((n) => addIds(n));
        case ARRAY_TYPE.ambaniFamily:
            return ambaniFamily.map((n) => addIds(n));
        case ARRAY_TYPE.britishRoyalFamily:
            return britishRoyalFamily.map((n) => addIds(n));
        case ARRAY_TYPE.designPatternsTreeData:
            return designPatternsTreeData.map((n) => addIds(n));
        case ARRAY_TYPE.continentData:
            return continentData.map((n) => addIds(n));
        case ARRAY_TYPE.treeDataProcessAndDisplayWithReactArcherSteps:
            return treeDataProcessAndDisplayWithReactArcherSteps.map((n) => addIds(n));
        case ARRAY_TYPE.programmingLanguagesTreeData:
            return programmingLanguagesTreeData.map((n) => addIds(n));
        default:
            return [];
    }
};

const generateTreeData = (depth = 1, itemsPerLevel = 1) => {
    let uniqueId = 1;

    const generateChildren = (parentId, currentDepth) => {
        if (currentDepth >= depth) return [];

        const children = [];
        for (let i = 0; i < itemsPerLevel; i++) {
            const id = uniqueId++;
            const node = {
                uniqueId: id,
                name: `Item ${id}`,
                children: generateChildren(id, currentDepth + 1),
                parentId: parentId,
                currentDepth,
            };

            children.push(node);
        }

        return children;
    };

    // Initialize the root nodes
    const data = generateChildren(0, 0);

    return data ? data.map((n) => addIds(n, true)) : [];
    // return rootNodes;
};




export {
    generateTreeData,
    ARRAY_TYPE,
    getUpdatedNameArrForType,
};

