// Function to add level and parentId fields, including showChildren
const addLevelAndParentIdField = (nodes = [], addExtraFieldCallback = () => ({})) => {
    const isValidFunction = typeof addExtraFieldCallback === 'function';

    const add = (nodes = [], currentLevel = 0, parentId = "") => {
        return nodes.map(node => {
            const updatedNode = {
                ...node,
                level: currentLevel,
                parentId,
                ...(isValidFunction ? addExtraFieldCallback(node) : {})
            };

            if (updatedNode.children && updatedNode.children.length > 0) {
                updatedNode.children = add(updatedNode.children, currentLevel + 1, updatedNode.uniqueId);
            }

            return updatedNode;
        });
    };

    return add(nodes, 0, "");
};



// Function to flatten tree data
const flattenTreeData = (nodes, filterCondition=()=>{return true;}) => {
    const result = [];

    const flatten = (node) => {
        result.push({ ...node });
        if (node.children && (!filterCondition || filterCondition(node))) {
            node.children.forEach(flatten);
        }
    };

    nodes.forEach(flatten);

    return result;
};

// Function to filter nodes by level
const filterByLevel = (data, level) =>
    data.filter(node => node.level === level);

// Function to filter nodes by a specific field value
const filterByValueForGivenField = (data, value, fieldName = "level") =>
    data.filter(node => node[fieldName] === value);

// Function to get distinct parent IDs
const getDistinctParentIds = (flattenedData) => {
    const parentIds = new Set(flattenedData.map(node => node.parentId));
    return [...parentIds].sort();
};

// Function to get distinct values for a specific field
const getDistinctValueForGivenField = (flattenedData, fieldName = "parentId") => {
    const values = new Set(flattenedData.map(node => node[fieldName]));
    return [...values].sort();
};

// Function to update showChildren for a node by uniqueID
const updateShowChildrenById = (nodes, uniqueID) =>
    nodes.map(node => {
        if (node.uniqueID === uniqueID) {
            return { ...node, showChildren: !node.showChildren };
        }
        if (node.children) {
            return {
                ...node,
                children: updateShowChildrenById(node.children, uniqueID),
            };
        }
        return node;
    });

