const TransformTreeDataGroupByLevelAndParentId = ({ data = [] }) => {
    const [newTreeData, setNewTreeData] = useState([]);
    const [stepDataArr, setStepDataArr] = useState([]);

    useEffect(() => {
        if (!data || data.length === 0) return;

        const steps = [];

        // Step 1: Initial raw data
        steps.push({ title: "Get Raw tree data", metadata: data });

        // Step 1.1: add level and parentId fields
        const withExtraRequiredFields= addLevelAndParentIdField(data);
        steps.push({ title: "Add level and parentId fields", metadata: withExtraRequiredFields });

        // Step 2: Flatten the array (if necessary)
        const flattenedData = flattenTreeData(data);
        steps.push({ title: "Get Flatten array", metadata: flattenedData });

        // Step 3: Get all distinct levels
        const levels = [...new Set(flattenedData.map(item => item.level))];
        steps.push({ title: "Get All distinct levels", metadata: levels });

        // Step 4: Get all distinct parent IDs for each level
        const parentIdsByLevel = groupParentIdsByLevel(flattenedData, levels);
        steps.push({ title: "Get All distinct parent ids for each level", metadata: parentIdsByLevel });

        // Step 5: Create level and section data
        const levelSections = createLevelSections(flattenedData, parentIdsByLevel);
        steps.push({ title: "Create levelSection data", metadata: levelSections });

        // Step 6: Final processing
        const finalData = groupByParentIdAndLevel(flattenedData);
        setNewTreeData(finalData);
        steps.push({ title: "Finally processed data", metadata: finalData });

        setStepDataArr(steps);

    }, [data]);

    // Helper Function to add level and parentId fields, including showChildren
    const addLevelAndParentIdField = (nodes = [], currentLevel = 0, parentId = "") =>
        nodes.map(node => {
            const updatedNode = { ...node, level: currentLevel, parentId, showChildren: false };

            if (updatedNode.children) {
                updatedNode.children = addLevelAndParentIdField(updatedNode.children, currentLevel + 1, updatedNode.uniqueID);
            }

            return updatedNode;
        });

    // Helper function to flatten the tree data (if required)
    const flattenTreeData = (arr) => {
        const flattened = [];

        const recurse = (node, level = 0) => {
            flattened.push({ ...node, children: [], level });
            if (node.children) {
                node.children.forEach(child => recurse(child, level + 1));
            }
        };

        arr.forEach(rootNode => recurse(rootNode));
        return flattened;
    };



    // Helper function to group parent IDs by level
    const groupParentIdsByLevel = (data, levels) => {
        return levels.map(level => ({
            level,
            parentIds: [...new Set(data.filter(item => item.level === level).map(item => item.parentId))]
        }));
    };

    // Helper function to create sections for each level
    const createLevelSections = (data, parentIdsByLevel) => {
        return parentIdsByLevel.map(({ level, parentIds }) => ({
            level,
            sections: parentIds.map(parentId => ({
                parentId,
                nodes: data.filter(item => item.level === level && item.parentId === parentId)
            }))
        }));
    };

    // Main function to group data by parent ID and level
    const groupByParentIdAndLevel = (arr) => {
        const groupedByParentId = arr.reduce((acc, item) => {
            if (!acc[item.parentId]) {
                acc[item.parentId] = [];
            }
            acc[item.parentId].push(item);
            return acc;
        }, {});

        const buildTree = (parentId = 'super-parent', level = 0) => {
            const nodesAtLevel = groupedByParentId[parentId] || [];

            return nodesAtLevel
                .filter(node => node.level === level)
                .map(node => ({
                    ...node,
                    children: buildTree(node.uniqueId, level + 1),
                }));
        };

        return buildTree();
    };

    return (
        <>
            <h1>
                Transform given tree data into a new array, containing objects of level.
                Each level object will contain sections. Each section will contain
                nodes.
            </h1>

            <h2>Step Details:-</h2>
            {stepDataArr.map(({ id, title, metadata }) => (
                <JSONDataViewer key={id} step={id} title={title} metadata={metadata} />
            ))}

            <h2>Final Outcome:-</h2>
            <JSONDataViewer title={"Final Data"} metadata={newTreeData} initialValueToShowMetadata={true} />
        </>
    );
};

export default TransformTreeDataGroupByLevelAndParentId;

