      <div id="endDiv" style={{ width: '100px', height: '100px', background: 'blue', margin: '50px' }}>End</div>
      <ArrowConnector startId="startDiv" endId="endDiv" />
    </div>
  );
};

export default ArrowConnectorExample;
export { ArrowConnector };
