const toggleShowChildrenForId = (id) => {
    setDataWithLevelAndParentIdField(prevData => {
        // Find the node with the given id
        const node = prevData.find(node => node.uniqueID === id);

        // Check if the node exists and is a root node
        if (node && !node.parentId) {
            // Toggle the showChildren property for the root node
            const updatedData = updateShowChildrenById(prevData, id, !node.showChildren);
            return updatedData;
        }

        // If the node is not found or is not a root node, return the original data
        return prevData;
    });
};
