// Function to add level and parentId fields
const addLevelAndParentIdField = (nodes = [], currentLevel = 0, parentId = "") => {
    return nodes.map((node) => {
        const updatedNode = { ...node, level: currentLevel, parentId };

        if (updatedNode.children) {
            updatedNode.children = addLevelAndParentIdField(
                updatedNode.children,
                currentLevel + 1,
                updatedNode.uniqueID
            );
        }

        return updatedNode;
    });
};

// Function to flatten tree data
const flattenTreeData = (nodes) => {
    const result = [];

    const flatten = (node) => {
        result.push({ ...node });
        if (node.children) {
            node.children.forEach(child => flatten(child));
            delete node.children; // Optionally remove children from the node after processing
        }
    };

    nodes.forEach(node => flatten(node));

    return result;
};

// Function to filter nodes by level
const filterByLevel = (data, level) => {
    return data.filter(node => node.level === level);
};

