        justifyContent: "space-between",
    },
    boxStyle: generateStyles("10px", "1px solid black"),
};

// Recursive component to render each node and its children
const RenderArcherBoxes = ({ node, level, styles }) => {
    const archerBoxes = useMemo(() => {
        const relations = getArcherElementRelations(
            node.children,
            { target: "top", source: "bottom" }
        );
        return (
            <>
                <ArcherBox
                    id={node.uniqueId}
                    relations={relations}
                    label={node.name}
                    style={styles.boxStyle}
                />
                {node.children && node.children.length > 0 && (
                    <ArcherRow style={styles.rowStyle}>
                        {node.children.map((child) => (
                            <RenderArcherBoxes
                                key={child.uniqueId}
                                node={child}
                                level={level + 1}
                                styles={styles}
                            />
                        ))}
                    </ArcherRow>
                )}
            </>
        );
    }, [node, level, styles]);

    return archerBoxes;
};

