Yes, you can modify the `useTreeData` hook to return a function that generates `nodeChildrenCompArr` for a given `levelData`. This allows you to encapsulate the logic within the hook and make it reusable across different components. Here's how you can implement it:

### `useTreeData.js` (Hook)
```javascript
import { useMemo } from "react";
import {
    addLevelAndParentIdField,
    filterByLevel,
    filterByValueForGivenField,
    flattenTreeData,
    getDistinctParentIds,
} from "../../common/utils/array-operation-utils";

const useTreeData = (data) => {
    const dataWithLevelAndParentIdField = useMemo(
        () => addLevelAndParentIdField(data),
        [data]
    );

    const flattenedData = useMemo(() => flattenTreeData(dataWithLevelAndParentIdField), [dataWithLevelAndParentIdField]);

    const levelCompArr = useMemo(() => {
        let currentLevel = 0;
        const levelComponentArr = [];

        while (true) {
            const levelArr = filterByLevel(flattenedData, currentLevel);
            if (levelArr.length === 0) break;
            levelComponentArr.push({ level: currentLevel, levelData: levelArr });
            currentLevel++;
        }

        return levelComponentArr;
    }, [flattenedData]);

    const getNodeChildrenCompArr = (levelData) => {
        return useMemo(() => {
            const distinctParentIds = getDistinctParentIds(levelData);
            return distinctParentIds.map((parentId) => ({
                parentId,
                nodeChildrenData:
                    filterByValueForGivenField(levelData, parentId, "parentId") || [],
            }));
        }, [levelData]);
    };

    return { dataWithLevelAndParentIdField, levelCompArr, getNodeChildrenCompArr };
};

export default useTreeData;
```

