    const parentIds = new Set(flattenedData.map(node => node.parentId));
    return [...parentIds].sort();
};

// Function to get distinct values for a specific field
const getDistinctValueForGivenField = (flattenedData, fieldName = "parentId") => {
    const values = new Set(flattenedData.map(node => node[fieldName]));
    return [...values].sort();
};

