### **Step 2: Kafka Consumer Code**

Create a file named `consumer.js` and add the following code:

```javascript
const { Kafka } = require('kafkajs');

// Kafka configuration
const kafka = new Kafka({
  clientId: 'kafka-consumer',
  brokers: ['localhost:9092'] // Add your Kafka broker address here
});

// Consumer instance
const consumer = kafka.consumer({ groupId: 'example-group' });

const run = async () => {
  // Connect the consumer
  await consumer.connect();

  // Subscribe to the topic
  await consumer.subscribe({ topic: 'trip-plans', fromBeginning: true });

  console.log('Kafka consumer is listening...');

  // Start consuming messages
  await consumer.run({
    eachMessage: async ({ topic, partition, message }) => {
      console.log(`Received message from topic ${topic}:`);
      console.log(`Partition: ${partition}`);
      console.log(`Offset: ${message.offset}`);
      console.log(`Key: ${message.key ? message.key.toString() : 'null'}`);
      console.log(`Value: ${message.value.toString()}`);
    }
  });
};

// Handle errors
run().catch(e => {
  console.error(`[Kafka Consumer Error]: ${e.message}`, e);
  process.exit(1);
});
```

