To implement this functionality, you can use `ejs` for rendering the HTML, and a library like `puppeteer` to generate the PDF on the server-side. Here's an example:

### 1. **Server-Side Setup**
```javascript
const express = require('express');
const puppeteer = require('puppeteer');
const path = require('path');

const app = express();
app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));

// Route to render HTML or download PDF
app.get('/generate', async (req, res) => {
    const { print } = req.query;

    // Render the HTML content
    const htmlContent = await new Promise((resolve, reject) => {
        res.render('template', { title: 'My EJS Page' }, (err, html) => {
            if (err) reject(err);
            resolve(html);
        });
    });

    if (print === 'true') {
        try {
            // Use Puppeteer to generate PDF
            const browser = await puppeteer.launch();
            const page = await browser.newPage();
            await page.setContent(htmlContent);
            const pdfBuffer = await page.pdf({ format: 'A4' });
            await browser.close();

            // Set headers for PDF download
            res.set({
                'Content-Type': 'application/pdf',
                'Content-Disposition': 'attachment; filename="output.pdf"',
            });

            return res.send(pdfBuffer);
        } catch (error) {
            console.error('Error generating PDF:', error);
            return res.status(500).send('Failed to generate PDF');
        }
    }

    // Return the HTML if not printing
    res.send(htmlContent);
});

// Start server
app.listen(3000, () => {
    console.log('Server running at http://localhost:3000');
});
```

---

### 2. **EJS Template (`views/template.ejs`)**
