   import React from "react";
   import dynamic from "next/dynamic";

   const ClientWrapper = dynamic(() => import("../components/ClientWrapper"), {
     ssr: false, // Disable SSR for client-only components
   });

   export default function Home() {
     return (
       <div>
         <h1>Library Example</h1>
         <ClientWrapper />
       </div>
     );
   }
   ```

---

### 3. Use Dynamic Imports with Client-Only Option
If you don’t want to restructure your components, you can dynamically import the library's component with `ssr: false`. This tells Next.js to load the component only on the client side.

#### Example:
```tsx
