Dynamic pool resizing can also be implemented in **Python**:

#### **Dynamic Connection Pool**
```python
import threading
from queue import Queue
from time import sleep
from threading import Timer

class Connection:
    def __init__(self, id):
        self.id = id

    def connect(self):
        print(f"Connecting using connection {self.id}")

    def disconnect(self):
        print(f"Disconnecting connection {self.id}")


class DynamicConnectionPool:
    _instance = None
    _lock = threading.Lock()

    def __init__(self, initial_size, max_size):
        self.pool = Queue(maxsize=max_size)
        self.max_size = max_size
        self.all_connections = []
        self.initial_size = initial_size

        for i in range(initial_size):
            connection = Connection(i + 1)
            self.pool.put(connection)
            self.all_connections.append(connection)

        # Start idle connection cleanup
        self._start_cleanup()

    @classmethod
    def get_instance(cls, initial_size, max_size):
        with cls._lock:
            if cls._instance is None:
                cls._instance = DynamicConnectionPool(initial_size, max_size)
            return cls._instance

    def get_connection(self):
        with self._lock:
            if self.pool.empty() and len(self.all_connections) < self.max_size:
                new_id = len(self.all_connections) + 1
                new_connection = Connection(new_id)
                self.all_connections.append(new_connection)
                self.pool.put(new_connection)
                print(f"Pool expanded: Connection {new_id} added.")
            return self.pool.get()

    def release_connection(self, connection):
        self.pool.put(connection)

    def _start_cleanup(self):
        def cleanup():
            with self._lock:
                while self.pool.qsize() > self.initial_size:
                    connection = self.pool.get()
                    self.all_connections.remove(connection)
                    print(f"Pool shrunk: Connection {connection.id} removed.")

        # Schedule cleanup every 60 seconds
        Timer(60, cleanup).start()


# Usage
if __name__ == "__main__":
    pool = DynamicConnectionPool.get_instance(3, 5)  # Initial size 3, max size 5

    # Acquire connections
    conn1 = pool.get_connection()
    conn1.connect()

    conn2 = pool.get_connection()
    conn2.connect()

    conn3 = pool.get_connection()
    conn3.connect()

    # Trigger pool expansion
    conn4 = pool.get_connection()
    conn4.connect()

    # Release connections
    conn1.disconnect()
    pool.release_connection(conn1)

    conn2.disconnect()
    pool.release_connection(conn2)

    # Wait to observe shrinking (requires 60 seconds)
    sleep(2)
```

