I understand how frustrating this can be! The error you're encountering happens because, in Next.js, the file is being treated as a **server-side component** by default, and `useState` (which is a React hook) only works in **client-side components**.

To resolve this, you need to explicitly mark your component as a **client-side component** by adding the `"use client"` directive at the top of your file.

### Solution:

Add the `"use client"` directive at the very top of your component file to mark it as a **client-side component**. This will allow React hooks like `useState` and `useEffect` to work properly.

### Updated Code:

```tsx
"use client"; // <-- Add this line to make this file a client component

import Link from "next/link";
import { useState } from "react";
import { useRouter } from "next/navigation";

export default function RBACV3({ searchParams }: { searchParams: { message?: string } }) {
  const [message, setMessage] = useState(searchParams.message || "");
  const router = useRouter();

  // Handle the login logic on the client-side using fetch
  const handleLogin = async (event: React.FormEvent) => {
    event.preventDefault();

    const formData = new FormData(event.target as HTMLFormElement);
    const email = formData.get("email");
    const password = formData.get("password");

    try {
      const res = await fetch("http://localhost:3000/api/v1/auth", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

