```tsx
import ClassicEditor from "@ckeditor/ckeditor5-build-classic";
import { CKEditor } from "@ckeditor/ckeditor5-react";
import yaml from "js-yaml";
import React, { useEffect, useRef, useState, useMemo, useContext } from "react";
import { buildTree } from "../../../util/indentation-based-string-parser-to-tree-data";
import CustomButton from "../../custom-button/CustomButton";
import JSONDataViewer from "../../json-data-viewer/JSONDataViewer";
import { getKeyName, inputOutputMapping, SupportedInputComponents, SupportedOutFormats } from "../common/utils.v4";
import SmartPreviewer from "../Previewer/v4";

// Context for global configurations (optional, can be extended)
const SmartEditorContext = React.createContext();

const SmartEditor = ({ initialValue, preview: previewInitialValue = true, onChange = () => {}, onError = () => {} }) => {
  const textareaRef = useRef(null);

  const [showPreview, setShowPreview] = useState(previewInitialValue);
  const [selectedOutputType, setSelectedOutputType] = useState(
    getKeyName(initialValue?.textOutputType, initialValue?.textInputType)
  );

  const formData = useMemo(() => {
    const { textOutputType, textInputType } = inputOutputMapping[selectedOutputType] || {};
    return {
      content: initialValue?.content || "",
      textOutputType,
      textInputType,
    };
  }, [selectedOutputType, initialValue]);

  const [content, setContent] = useState(formData.content);
  const [error, setError] = useState("");

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight * 1.3}px`;
    }
  }, [content]);

  useEffect(() => {
    let errorMsg = "";

    if (formData.textOutputType === SupportedOutFormats.YAML && content) {
      try {
        yaml.load(content);
      } catch (e) {
        errorMsg = `Error parsing YAML: ${e.message}`;
      }
    }

    if (formData.textOutputType === SupportedOutFormats.TIS_to_SKELETON && content) {
      const { isValid, message } = buildTree(content);
      if (!isValid) errorMsg = message;
    }

    if (!content.trim()) errorMsg = "Content is empty";

    setError(errorMsg);
    onError(errorMsg);
    onChange({ ...formData, content });
  }, [content, formData.textOutputType]);

  return (
    <SmartEditorContext.Provider value={{ formData, error, selectedOutputType, setSelectedOutputType }}>
      <div>
        <OutputTypeSelector />
        <EditorContent content={content} setContent={setContent} textareaRef={textareaRef} />
        {error && <FormError message={error} />}
        {content && (
          <div>
            <b>Preview:</b> <CustomButton onClick={() => setShowPreview((prev) => !prev)}>{showPreview ? "Hide" : "Show"}</CustomButton>
          </div>
        )}
        {showPreview && <SmartPreviewer data={{ ...formData, content }} />}
        <JSONDataViewer metadata={{ selectedOutputType }} title="selectedOutputType" />
      </div>
    </SmartEditorContext.Provider>
  );
};

// Subcomponent: Output Type Selector
const OutputTypeSelector = () => {
  const { selectedOutputType, setSelectedOutputType } = useContext(SmartEditorContext);
  return (
    <div>
      <label htmlFor="outputType" className="font-bold">
        Select Output Type:
      </label>
      <select
        value={selectedOutputType}
        title={inputOutputMapping[selectedOutputType]?.detailedName || ""}
        onChange={(e) => setSelectedOutputType(e.target.value)}
        className="border p-2 rounded w-full"
      >
        {Object.keys(inputOutputMapping).map((outputType) => (
          <option key={outputType} value={outputType}>
            {outputType.replace(/_/g, " ")}
          </option>
        ))}
      </select>
    </div>
  );
};

// Subcomponent: Editor Content (TextArea / CKEditor)
const EditorContent = ({ content, setContent, textareaRef }) => {
  const { formData } = useContext(SmartEditorContext);

  if (formData.textInputType === SupportedInputComponents.ckEditor) {
    return (
      <div>
        <label htmlFor="ckeditor" className="font-bold">
          Content:
        </label>
        <CKEditor id="ckeditor" name="content" editor={ClassicEditor} data={content} onChange={(_, editor) => setContent(editor.getData())} />
      </div>
    );
  }

  return (
    <div>
      <label htmlFor="content" className="font-bold">
        Content:
      </label>
      <textarea
        ref={textareaRef}
        id="content"
        name="content"
        value={content}
        onChange={(e) => setContent(e.target.value)}
        className="w-full p-2 text-lg border rounded resize-none overflow-hidden"
      />
    </div>
  );
};

// Subcomponent: Error Display
const FormError = ({ message }) => (
  <div className="text-red-500 font-semibold mt-2 bg-red-100 p-2 rounded">
    ⚠️ {message}
  </div>
);

export { SmartEditor as SmartEditorV4 };
```

---

### **Key Improvements**
1. **useMemo for `formData`** → Prevents unnecessary re-calculations.  
2. **useContext for Shared State** → Simplifies passing state to subcomponents.  
3. **Separate Components:**
   - `<OutputTypeSelector />`
   - `<EditorContent />`
   - `<FormError />` (Handles error messages cleanly)  
4. **Tailwind Styles** → More compact and responsive.  

