### **Step 4: Create an API Route for Login**  
Inside `next-rbac-app/src/pages/api/auth/login.ts`:  

```ts
import type { NextApiRequest, NextApiResponse } from "next";
import jwt from "jsonwebtoken";
import { users } from "@/data/users";

const SECRET_KEY = "mysecretkey"; // Store in .env in real apps

export default function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== "POST") {
    return res.status(405).json({ message: "Method Not Allowed" });
  }

  const { email, password } = req.body;
  const user = users.find((u) => u.email === email && u.password === password);

  if (!user) {
    return res.status(401).json({ message: "Invalid email or password" });
  }

  // Generate JWT token with role
  const token = jwt.sign({ id: user.id, email: user.email, role: user.role }, SECRET_KEY, {
    expiresIn: "1h",
  });

  res.status(200).json({ token });
}
```

---

### **Step 5: Protect API Routes with RBAC**  
Inside `next-rbac-app/src/pages/api/protected.ts`:  

```ts
import type { NextApiRequest, NextApiResponse } from "next";
import jwt from "jsonwebtoken";

const SECRET_KEY = "mysecretkey";

export default function handler(req: NextApiRequest, res: NextApiResponse) {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ message: "Unauthorized" });
  }

  const token = authHeader.split(" ")[1];

  try {
    const decoded = jwt.verify(token, SECRET_KEY) as { role: string };
    if (decoded.role !== "admin") {
      return res.status(403).json({ message: "Forbidden: Insufficient Permissions" });
    }
    return res.status(200).json({ message: "Welcome Admin! You have access." });
  } catch (error) {
    return res.status(401).json({ message: "Invalid or Expired Token" });
  }
}
```

