const structure = builder
  .addSection("Introduction")
    .addSubSection("Basics")
      .addQuestions("What is JavaScript?", "What are variables?")
  .addSection("Advanced Topics")
    .addSubSection("Asynchronous Programming")
      .addQuestions("What is a Promise?", "What is async/await?")
    .addSubSection("Design Patterns")
      .addQuestion("What is the Singleton pattern?")
  .build();

