### **Optimized `SmartEditorV4.js`**
```jsx
import ClassicEditor from "@ckeditor/ckeditor5-build-classic";
import { CKEditor } from "@ckeditor/ckeditor5-react";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import JSONDataViewer from "../../json-data-viewer/JSONDataViewer";
import {
  getDetailedName,
  SupportedInputComponents,
  getInpOupDetailsForKey,
  getComboOptions,
  getKeyName,
  validateSmartContent,
} from "../common/utils.v4";
import SmartPreviewer from "../Previewer/v4";
import FormMessagesV1 from "../../FormMessages/v1";

const SmartEditorV4 = ({
  initialValue = { content: "", textOutputType: "", textInputType: "" },
  preview: previewInitialValue = true,
  onSubmit = async () => ({ isError: false, messages: [] }),
}) => {
  const [showPreview, setShowPreview] = useState(previewInitialValue);
  const [formMessages, setFormMessages] = useState([]);
  const [formData, setFormData] = useState(initialValue);

  useEffect(() => setFormData(initialValue), [initialValue]);

  const { detailedName, selectedOutputType } = useMemo(() => ({
    selectedOutputType: getKeyName(formData.textOutputType, formData.textInputType),
    detailedName: getDetailedName(formData.textOutputType, formData.textInputType),
  }), [formData.textInputType, formData.textOutputType]);

  const handleFormUpdate = useCallback((content, newOutputType = selectedOutputType) => {
    const { textInputType, textOutputType } = getInpOupDetailsForKey(newOutputType);
    setFormMessages(validateSmartContent(content, textOutputType));

    setFormData({
      content,
      textOutputType: textOutputType || formData.textOutputType,
      textInputType: textInputType || formData.textInputType,
    });
  }, [selectedOutputType, formData.textInputType, formData.textOutputType]);

  const handleChangeOutputTypes = useCallback((newOutputType) => {
    if (typeof newOutputType !== "string") {
      setFormMessages([{ type: "error", message: `Invalid newOutputType: '${newOutputType}'` }]);
      return;
    }
    handleFormUpdate(formData.content, newOutputType);
  }, [handleFormUpdate, formData.content]);

  const updateFormContent = useCallback((content = "") => {
    if (!content.trim()) {
      setFormMessages([{ type: "error", message: "Content cannot be empty" }]);
    }
    handleFormUpdate(content);
  }, [handleFormUpdate]);

  const handleSave = async () => {
    const result = await onSubmit(formData);
    setFormMessages(result.isError ? result.messages : []);
  };

  const handleReset = () => setFormData(initialValue);

  return (
    <div className="container">
      {/* Output Type Selection */}
      <div className="form-floating">
        <select
          className="form-select"
          id="OutputTypeCombobox"
          value={selectedOutputType}
          title={detailedName || ""}
          onChange={(e) => handleChangeOutputTypes(e.target.value)}
        >
          {getComboOptions()}
        </select>
        <label htmlFor="OutputTypeCombobox" style={{ fontWeight: "bold" }}>
          Select Output Type:
        </label>
      </div>

      {/* Textarea Input */}
      {formData.textInputType === SupportedInputComponents.textArea && (
        <div className="form-floating">
          <textarea
            id="content"
            name="content"
            className="form-control"
            value={formData.content}
            onChange={(e) => updateFormContent(e.target.value)}
            style={{ height: "300px" }}
          />
          <label htmlFor="content" style={{ fontWeight: "bold" }}>
            Content:
          </label>
        </div>
      )}

      {/* CKEditor Input */}
      {formData.textInputType === SupportedInputComponents.ckEditor && (
        <div className="form-floating">
          <CKEditor
            id="ckeditor"
            name="ckeditorContent"
            editor={ClassicEditor}
            data={formData.content}
            onChange={(event, editor) => updateFormContent(editor.getData())}
          />
        </div>
      )}

      {/* Buttons */}
      <div className="d-flex justify-content-end mt-2">
        <button className="btn btn-outline-secondary me-2" onClick={handleReset}>
          Reset
        </button>
        <button className="btn btn-primary" onClick={handleSave}>
          Save
        </button>
      </div>

      {/* Form Messages */}
      <FormMessagesV1 messages={formMessages} />

      {/* Preview Button */}
      {formData.content && (
        <div>
          <button
            className="btn btn-info btn-sm p-1 m-1 text-uppercase"
            onClick={() => setShowPreview((prev) => !prev)}
          >
            {showPreview ? "Hide Preview" : "Show Preview"}
          </button>
          {showPreview && <SmartPreviewer data={formData} />}
        </div>
      )}

      {/* Debug Viewer */}
      {false && <JSONDataViewer metadata={{ formData }} title="selectedOutputType" />}
    </div>
  );
};

export default SmartEditorV4;
```

---

### **Optimizations Applied**
1. **Removed unnecessary `if` conditions** (e.g., `if (newContent == null) return;`).
2. **Used `useEffect` to initialize `formData` state** instead of manual updates.
3. **Avoided unnecessary function calls**:
   - `handleChangeOutputTypes` now directly calls `handleFormUpdate`, reducing redundant checks.
4. **Simplified `handleSave`**:
   - No need for a separate `console.log`.
5. **Simplified `handleReset`**:
   - Directly resets `formData` instead of setting each field individually.
6. **Removed unnecessary debugging conditions** while keeping the `JSONDataViewer` option.

---

### **Why is this better?**
✔ **Less boilerplate** → Easier to read & maintain  
✔ **More efficient state updates** → Avoids unnecessary re-renders  
✔ **Single-responsibility functions** → `handleFormUpdate` handles all form state updates  
