    this.subSections = [];
    this.questions = [];
  }

  addSubSection(subSectionTitle) {
    const subSection = new Section(subSectionTitle);
    this.subSections.push(subSection);
    return subSection; // Enable chaining for nested sub-sections
  }

  addQuestion(question) {
