import React, { useState } from "react";
import { NavLink } from "react-router-dom";
import { myDataSources } from "./data";
import Table from "./Table";

const PaginationNavigator = ({ currentPage, totalPages, onPageChange }) => {
  const createPageLinks = () => {
    const links = [];
    for (let i = 1; i <= totalPages; i++) {
      links.push(
        <li className={`page-item ${i === currentPage ? "active" : ""}`} key={i}>
          <button className="page-link" onClick={() => onPageChange(i)}>
            {i}
          </button>
        </li>
      );
    }
    return links;
  };

  return (
    <nav aria-label="Page navigation">
      <ul className="pagination pagination-sm justify-content-center">
        <li className={`page-item ${currentPage === 1 ? "disabled" : ""}`}>
          <button
            className="page-link"
            onClick={() => onPageChange(currentPage - 1)}
            disabled={currentPage === 1}
          >
            Previous
          </button>
        </li>
        {createPageLinks()}
        <li className={`page-item ${currentPage === totalPages ? "disabled" : ""}`}>
          <button
            className="page-link"
            onClick={() => onPageChange(currentPage + 1)}
            disabled={currentPage === totalPages}
          >
            Next
          </button>
        </li>
      </ul>
    </nav>
  );
};

const PageSize = 5;

const SourceDetailsV1 = () => {
  const [currentPage, setCurrentPage] = useState(1);

  const totalPages = Math.ceil(myDataSources.length / PageSize);

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const filteredItems = myDataSources.slice(
    (currentPage - 1) * PageSize,
    currentPage * PageSize
  );

  return (
    <div className="container">
      <h2 className="text-center my-4">Source Details</h2>
      <PaginationNavigator
        currentPage={currentPage}
        totalPages={totalPages}
        onPageChange={handlePageChange}
      />
      <Table filteredItems={filteredItems} />
      <PaginationNavigator
        currentPage={currentPage}
        totalPages={totalPages}
        onPageChange={handlePageChange}
      />
    </div>
  );
};

export default SourceDetailsV1;
```

### Key Features:
1. **Pagination State**:
   - `currentPage` tracks the active page.
   - The total number of pages is calculated dynamically using `Math.ceil`.

2. **Dynamic Page Links**:
   - The `PaginationNavigator` generates page links dynamically based on `totalPages`.
   - Handles "Previous" and "Next" buttons with appropriate disabling logic.

3. **Data Slicing**:
