import type { NextApiRequest, NextApiResponse } from "next";
import jwt from "jsonwebtoken";

const SECRET_KEY = "mysecretkey";

export default function handler(req: NextApiRequest, res: NextApiResponse) {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ message: "Unauthorized" });
  }

  const token = authHeader.split(" ")[1];

  try {
    const decoded = jwt.verify(token, SECRET_KEY) as { role: string };
    if (decoded.role !== "admin") {
      return res.status(403).json({ message: "Forbidden: Insufficient Permissions" });
    }
    return res.status(200).json({ message: "Welcome Admin! You have access." });
  } catch (error) {
    return res.status(401).json({ message: error instanceof Error ? error.message : "Invalid or Expired Token" });
  }
}

