```jsx
import ClassicEditor from "@ckeditor/ckeditor5-build-classic";
import { CKEditor } from "@ckeditor/ckeditor5-react";
import yaml from "js-yaml";
import React, { useEffect, useMemo, useState, useRef, useContext } from "react";
import { buildTree } from "../../../util/indentation-based-string-parser-to-tree-data";
import CustomButton from "../../custom-button/CustomButton";
import JSONDataViewer from "../../json-data-viewer/JSONDataViewer";
import { getKeyName, inputOutputMapping, SupportedInputComponents, SupportedOutFormats } from "../common/utils.v4";
import SmartPreviewer from "../Previewer/v4";

// Assuming SmartEditorContext exists in your app
const SmartEditorContext = React.createContext();

const FormError = ({ error }) => {
  if (!error) return null;
  return <div className="alert alert-danger mt-2">{error}</div>;
};

const SmartEditor = ({ initialValue, preview: previewInitialValue = true, onChange = () => {}, onError = () => {} }) => {
  const textareaRef = useRef(null);
  const { updateEditorState } = useContext(SmartEditorContext); // Example context usage

  const [selectedOutputType, setSelectedOutputType] = useState(
    getKeyName(initialValue?.textOutputType, initialValue?.textInputType)
  );
  const [showPreview, setShowPreview] = useState(previewInitialValue);
  const [error, setError] = useState("");

  const selectedMapping = useMemo(() => inputOutputMapping[selectedOutputType], [selectedOutputType]);

  const [formData, setFormData] = useState({
    content: initialValue?.content || "",
    textOutputType: selectedMapping.textOutputType,
    textInputType: selectedMapping.textInputType,
  });

  useEffect(() => {
    setFormData((prev) => ({
      ...prev,
      textInputType: selectedMapping.textInputType,
      textOutputType: selectedMapping.textOutputType,
    }));
  }, [selectedOutputType]);

  useEffect(() => {
    let validationError = "";
    const { textOutputType, content } = formData;

    if (textOutputType === SupportedOutFormats.YAML && content) {
      try {
        yaml.load(content);
      } catch (e) {
        validationError = `YAML Error: ${e.message}`;
      }
    }

    if (textOutputType === SupportedOutFormats.TIS_to_SKELETON && content) {
      const { isValid, message } = buildTree(content);
      if (!isValid) validationError = message;
    }

    if (!content.trim()) validationError = "Content cannot be empty.";

    setError(validationError);
    onError(validationError);
    onChange(formData);
  }, [formData]);

  const handleChangeOutputTypes = (event) => setSelectedOutputType(event.target.value);
  const handleInputChange = (e) => setFormData((prev) => ({ ...prev, content: e.target.value }));
  const handleEditorChange = (event, editor) => setFormData((prev) => ({ ...prev, content: editor.getData() }));

  return (
    <div className="container p-3">
      <div className="mb-3">
        <label htmlFor="outputType" className="form-label fw-bold">
          Select Output Type:
        </label>
        <select
          className="form-select"
          value={selectedOutputType}
          title={selectedMapping?.detailedName || ""}
          onChange={handleChangeOutputTypes}
        >
          {Object.keys(inputOutputMapping).map((outputType) => (
            <option key={outputType} value={outputType}>
              {outputType.replace(/_/g, " ")}
            </option>
          ))}
        </select>
      </div>

      {formData.textInputType === SupportedInputComponents.textArea && (
        <div className="mb-3">
          <label htmlFor="content" className="form-label fw-bold">
            Content:
          </label>
          <textarea
            ref={textareaRef}
            id="content"
            name="content"
            value={formData.content}
            onChange={handleInputChange}
            className="form-control"
            rows={5}
          />
        </div>
      )}

      {formData.textInputType === SupportedInputComponents.ckEditor && (
        <div className="mb-3">
          <label htmlFor="ckeditor" className="form-label fw-bold">
            Content:
          </label>
          <CKEditor id="ckeditor" name="content" editor={ClassicEditor} data={formData.content} onChange={handleEditorChange} />
        </div>
      )}

      <FormError error={error} />

      {formData.content && (
        <div className="mt-3">
          <b>Preview:</b>
          <CustomButton onClick={() => setShowPreview((prev) => !prev)} className="ms-2">
            {showPreview ? "Hide" : "Show"}
          </CustomButton>
        </div>
      )}

      {showPreview && <SmartPreviewer data={formData} />}
      <JSONDataViewer metadata={{ selectedOutputType }} title="Selected Output Type" />
    </div>
  );
};

export { SmartEditor as SmartEditorV4 };
```

---

### Summary of Improvements:
1. **Performance Optimization:**
   - Used `useMemo` for `selectedMapping` lookup.
   - Avoids unnecessary re-renders.

2. **Cleaner State Management:**
