### **Optimized Code:**
```tsx
import ClassicEditor from "@ckeditor/ckeditor5-build-classic";
import { CKEditor } from "@ckeditor/ckeditor5-react";
import React, { useCallback, useEffect, useState } from "react";
import JSONDataViewer from "../../json-data-viewer/JSONDataViewer";
import {
  getDetailedName,
  SupportedInputComponents,
  getInpOupDetailsForKey,
  getComboOptions,
  getKeyName,
  validateSmartContent,
} from "../common/utils.v4";
import SmartPreviewer from "../Previewer/v4";
import FormMessagesV1 from "../../FormMessages/v1";

const debug = false;

const SmartEditorV4 = ({
  initialValue = { content: "", textOutputType: "", textInputType: "" },
  preview: previewInitialValue = true,
  onSubmit = async () => ({ isError: false, messages: [] }),
}) => {
  const [showPreview, setShowPreview] = useState(previewInitialValue);
  const [formMessages, setFormMessages] = useState([]);
  const [formData, setFormData] = useState({ ...initialValue });

  const handleFormUpdate = useCallback((content, outputType) => {
    const { textInputType, textOutputType } = getInpOupDetailsForKey(outputType);
    setFormMessages(validateSmartContent(content, textOutputType));

    setFormData((prev) => ({
      content,
      textOutputType: textOutputType || prev.textOutputType,
      textInputType: textInputType || prev.textInputType,
    }));
  }, []);

  useEffect(() => {
    handleFormUpdate(initialValue.content, getKeyName(initialValue.textOutputType, initialValue.textInputType));
  }, [initialValue, handleFormUpdate]);

  const handleChangeOutputTypes = useCallback((newOutputType) => {
    if (typeof newOutputType !== "string") {
      setFormMessages([{ type: "error", message: `Invalid output type: '${newOutputType}'` }]);
      return;
    }
    handleFormUpdate(formData.content, newOutputType);
  }, [handleFormUpdate, formData.content]);

  const updateFormContent = useCallback((content = "") => {
    if (!content.trim()) {
      setFormMessages([{ type: "error", message: "Content cannot be empty" }]);
    }
    handleFormUpdate(content);
  }, [handleFormUpdate]);

  const handleSave = async () => {
    const result = await onSubmit(formData);
    setFormMessages(result.isError ? result.messages : result.messages ?? []);
  };

  const handleReset = () => setFormData({ ...initialValue });

  return (
    <div className="container">
      {/* Output Type Selection */}
      <div className="form-floating">
        <select
          className="form-select"
          id="OutputTypeCombobox"
          value={getKeyName(formData.textOutputType, formData.textInputType)}
          title={getDetailedName(formData.textOutputType, formData.textInputType)}
          onChange={(e) => handleChangeOutputTypes(e.target.value)}
        >
          {getComboOptions()}
        </select>
        <label htmlFor="OutputTypeCombobox" style={{ fontWeight: "bold" }}>
          Select Output Type:
        </label>
      </div>

      {/* Input Components */}
      {formData.textInputType === SupportedInputComponents.textArea ? (
        <div className="form-floating">
          <textarea
            id="content"
            name="content"
            className="form-control"
            value={formData.content}
            onChange={(e) => updateFormContent(e.target.value)}
            style={{ height: "300px" }}
          />
          <label htmlFor="content" style={{ fontWeight: "bold" }}>
            Content:
          </label>
        </div>
      ) : formData.textInputType === SupportedInputComponents.ckEditor ? (
        <div className="form-floating">
          <CKEditor
            id="ckeditor"
            name="ckeditorContent"
            editor={ClassicEditor}
            data={formData.content}
            onChange={(event, editor) => updateFormContent(editor.getData())}
          />
        </div>
      ) : null}

      {/* Buttons */}
      <div className="d-flex justify-content-end mt-2">
        <button className="btn btn-outline-secondary me-2" onClick={handleReset}>
          Reset
        </button>
        <button className="btn btn-primary" onClick={handleSave}>
          Save
        </button>
      </div>

      {/* Form Messages */}
      <FormMessagesV1 messages={formMessages} />

      {/* Preview Button */}
      {formData.content && (
        <div>
          <button className="btn btn-info btn-sm p-1 m-1 text-uppercase" onClick={() => setShowPreview((prev) => !prev)}>
            {showPreview ? "Hide Preview" : "Show Preview"}
          </button>
          {showPreview && <SmartPreviewer data={formData} />}
        </div>
      )}

      {debug && <JSONDataViewer metadata={{ formData }} title="selectedOutputType" />}
    </div>
  );
};

export default SmartEditorV4;
```

