### **🔧 Update Login Route for Role-Based Assignment**
#### **routes/authRoutes.ts**
```typescript
import express from "express";
import jwt from "jsonwebtoken";
import { roles } from "../config/roles";

const router = express.Router();
const JWT_SECRET = process.env.JWT_SECRET || "your_secret_key";
const JWT_EXPIRY = "1h"; // 1 hour expiration for demo

router.post("/login", (req, res) => {
  const { email } = req.body;

  if (!email) {
    return res.status(400).json({ message: "Email is required" });
  }

  // Assign role based on email pattern
  const role = email.startsWith("admin") ? "admin" : "user";

  // Generate JWT Token
  const token = jwt.sign({ email, role }, JWT_SECRET, { expiresIn: JWT_EXPIRY });

  res.json({ message: "Login successful", token });
});

export default router;
```

