#### Component Code
```javascript
import React, { useMemo, useCallback } from "react";
import useSPPNavigation from ".";
import styles from "./styles.module.css";
import * as ReactIconsFA from "react-icons/fa";
import buttonConfigData from "./buttonConfig"; // Import button config
import qids from "./qids"; // Import qids

// Safely fetch icon components by name
const getIcon = (name = "FaQuestionCircle") =>
  ReactIconsFA[name] || ReactIconsFA.FaQuestionCircle;

const UseNavigationExampleComponent = React.memo(() => {
  const navigation = useSPPNavigation();

  // Memoize button configuration with dynamic values
  const buttonConfig = useMemo(() => {
    return buttonConfigData.map((config) => {
      const { action, params = [], title } = config;
      const processedTitle = title.replace(/qids\[([0-9]+)\]/g, (_, idx) => qids[idx]);
      return {
        ...config,
        title: processedTitle,
        onClick: () => {
          const fn = navigation[action];
          if (fn) fn(...params.map((p) => (p.startsWith("qids") ? eval(p) : p))); // Resolve params dynamically
        },
      };
    });
  }, [navigation]);

  // Callback to render buttons
  const renderButton = useCallback(({ title, onClick, icon }, idx) => {
    const IconComponent = getIcon(icon);
    return (
      <button
        key={`button_${idx}`}
        className={styles.button}
        title={title}
        onClick={onClick}
      >
        <IconComponent className={styles.icon} /> {title}
      </button>
    );
  }, []);

  return (
    <div className={styles.container}>{buttonConfig.map(renderButton)}</div>
  );
});

export default UseNavigationExampleComponent;
```

---

### **Benefits of Externalizing Both `qids` and `buttonConfig`**

1. **Simplicity**:
   - No inline data manipulation. The config and IDs are handled in their respective files.
   - The component just processes and renders the configuration.

2. **Reusability**:
   - Both `qids` and `buttonConfig` can now be reused across different components or modules.

3. **Maintainability**:
   - Changes to `qids` or `buttonConfig` can be made independently without affecting the component logic.

4. **Scalability**:
   - Adding new actions or updating `qids` is straightforward, without increasing the complexity of the component.

By externalizing both, you make the entire codebase more modular and future-proof.

