import Link from "next/link";
import { redirect } from "next/navigation";

export default function RBACV3({ searchParams }: { searchParams: { message?: string } }) {
  const message = searchParams.message || "";

  // Server-side form submission handler
  async function handleLogin(formData: FormData) {
    const email = formData.get("email");
    const password = formData.get("password");

    const res = await fetch("http://localhost:3000/api/v1/auth", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });

    const data = await res.json();
    if (res.ok) {
      return redirect(`/v3?message=${encodeURIComponent("✅ Login Successful!")}`);
    } else {
      return redirect(`/v3?message=${encodeURIComponent(`❌ ${data.message}`)}`);
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-100 p-4">
      <div className="w-full max-w-md space-y-6 rounded-lg bg-white p-6 shadow-md">
        <h1 className="text-center text-2xl font-bold text-gray-800">🔒 RBAC v2</h1>

        {/* Form with action pointing to the `handleLogin` function */}
        <form action={handleLogin} method="POST" className="space-y-4">
          <input
            type="email"
            name="email"
            placeholder="Enter Email"
            className="w-full rounded-md border p-3"
            required
          />
          <input
            type="password"
            name="password"
            placeholder="Enter Password"
            className="w-full rounded-md border p-3"
            required
          />

          <button type="submit" className="w-full rounded-md bg-blue-500 p-3 text-white">
            🔑 Login
          </button>
        </form>

        {/* Display success/error message if it exists */}
        {message && <p className="mt-4 rounded-md bg-gray-200 p-3 text-center text-gray-800">{message}</p>}

        {/* Link to fetch protected data */}
        <Link
          href="/v1/protected"
          className="block w-full text-center rounded-md bg-green-500 p-3 text-white mt-4"
        >
          🔍 Fetch Protected Data
        </Link>
      </div>
    </div>
  );
}
```

### Key Points:
1. **Server-Side Submission:** The `handleLogin` function will be executed on the server, and it will redirect based on the result (success or error).
2. **No `useState`:** We are using query parameters (`searchParams`) to pass the message to the page rather than managing state on the client side.
3. **No `"use client"`:** The component remains fully server-rendered, as no React hooks like `useState` or `useEffect` are needed.

By handling the form logic on the server and passing messages via query parameters, we can avoid using `"use client"` and keep everything as server-rendered as possible.

