import { redirect } from "next/navigation";

export default async function RBACV2({ searchParams }: { searchParams: { message?: string } }) {
  const message = searchParams.message || "";

  // Handle the login logic on the server side using "POST"
  async function handleLogin(formData: FormData) {
    const email = formData.get("email");
    const password = formData.get("password");

    const res = await fetch("http://localhost:3000/api/v1/auth", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });

    const data = await res.json();

    // Use `redirect` after successful login to show the message in the query params
    if (res.ok) {
      return redirect(`/v2?message=${encodeURIComponent("✅ Login Successful!")}`);
    }
    return redirect(`/v2?message=${encodeURIComponent(`❌ ${data.message}`)}`);
  }

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-100 p-4">
      <div className="w-full max-w-md space-y-6 rounded-lg bg-white p-6 shadow-md">
        <h1 className="text-center text-2xl font-bold text-gray-800">🔒 RBAC v2</h1>

        {/* Form with action pointing to the `handleLogin` function */}
        <form action={handleLogin} method="POST" className="space-y-4">
          <input
            type="email"
            name="email"
            placeholder="Enter Email"
            className="w-full rounded-md border p-3"
            required
          />
          <input
            type="password"
            name="password"
            placeholder="Enter Password"
            className="w-full rounded-md border p-3"
            required
          />

          <button type="submit" className="w-full rounded-md bg-blue-500 p-3 text-white">
            🔑 Login
          </button>
        </form>

        {/* Display success/error message if it exists */}
        {message && <p className="mt-4 rounded-md bg-gray-200 p-3 text-center text-gray-800">{message}</p>}

        {/* Link to fetch protected data */}
        <Link
          href="/v1/protected"
          className="block w-full text-center rounded-md bg-green-500 p-3 text-white mt-4"
        >
          🔍 Fetch Protected Data
        </Link>
      </div>
    </div>
  );
}
```

### **Key Points:**

1. **Query Parameters Handling:**
   - **Server-Side Query Parameters:** The `message` query parameter is handled server-side, allowing the message to be rendered in the UI when the page is loaded.
   - We use `searchParams.message` to show any success or error messages from the query parameter. This ensures that the message is always visible after the redirect.

2. **No `use client`:** 
   - The code does not require the `"use client"` directive because it uses server-side handling for the form submission and message display. The form submission (`action={handleLogin}`) now directly calls the `handleLogin` function on the server side.

3. **Form Submission:**
   - The form is still being handled in a traditional way using `method="POST"`. When the form is submitted, the server-side logic in `handleLogin` handles the authentication and sends back the appropriate success or error message.

4. **Redirection:**
   - After a successful or failed login, we use the `redirect()` function from `next/navigation` to redirect the user to the `/v2` page, with a query parameter (`message`) that contains the status of the login attempt. The query parameter then gets passed to the component, allowing the message to be displayed.

### **Outcome:**
- The query message (`message`) will now be handled on the server side, and the component will be rendered correctly based on the response from the server.

