package com.p.node.service.nodes;

import com.p.node.service.base.response.ResponseMapper;
import com.p.node.service.base.response.StandardResponse;
import java.util.List;
import javax.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/nodes")
@RequiredArgsConstructor
public class NodeController {

  private final NodeService nodeService;

  @PostMapping(value = "", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<StandardResponse<Node>> createNode(@Valid @RequestBody Node node) {
    return ResponseMapper.createSuccessResponse(
        "Successfully created new Node", nodeService.saveNode(node), HttpStatus.CREATED);
  }

  @GetMapping(value = "", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<StandardResponse<List<Node>>> getAllNodes(
      @RequestParam(defaultValue = "0") int page,
      @RequestParam(defaultValue = "10") int size) {
