        "Successfully retrieved all Nodes", nodeService.getNodes(page, size), HttpStatus.OK);
  }

  @GetMapping(value = "/{id}", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<StandardResponse<Node>> getNodeById(@PathVariable String id) {
    return ResponseMapper.createSuccessResponse(
        "Successfully retrieved Node with id: " + id, nodeService.getNodeById(id), HttpStatus.OK);
  }

  @DeleteMapping(value = "/{id}", produces = MediaType.APPLICATION_JSON_VALUE)
  public ResponseEntity<StandardResponse<Void>> deleteNode(@PathVariable String id) {
    nodeService.deleteNode(id);
    return ResponseMapper.createSuccessResponse(
        "Successfully deleted data for id: " + id, HttpStatus.NO_CONTENT);
  }
}
