### **Test Class**

```java
package com.p.api.node.service.nodes;

import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import java.util.Arrays;
import java.util.List;
import java.util.Optional;

class NodeServiceTest {

    @Mock
    private NodeRepository nodeRepository;

    @InjectMocks
    private NodeService nodeService;

    @BeforeEach
    void setUp() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    void testSaveNode() {
        Node node = new Node("uniqueId1", null);
        when(nodeRepository.save(node)).thenReturn(node);

        Node savedNode = nodeService.saveNode(node);

        assertNotNull(savedNode);
        assertEquals("uniqueId1", savedNode.getUniqueId());
        verify(nodeRepository, times(1)).save(node);
    }

    @Test
    void testGetAllNodes() {
        Node node1 = new Node("uniqueId1", null);
        Node node2 = new Node("uniqueId2", null);
        when(nodeRepository.findAll()).thenReturn(Arrays.asList(node1, node2));

        List<Node> nodes = nodeService.getAllNodes();

        assertNotNull(nodes);
        assertEquals(2, nodes.size());
        assertEquals("uniqueId1", nodes.get(0).getUniqueId());
        assertEquals("uniqueId2", nodes.get(1).getUniqueId());
        verify(nodeRepository, times(1)).findAll();
    }

    @Test
    void testGetNodeById_NodeExists() {
        Node node = new Node("uniqueId1", null);
        when(nodeRepository.findById("uniqueId1")).thenReturn(Optional.of(node));

        Optional<Node> retrievedNode = nodeService.getNodeById("uniqueId1");

        assertTrue(retrievedNode.isPresent());
        assertEquals("uniqueId1", retrievedNode.get().getUniqueId());
        verify(nodeRepository, times(1)).findById("uniqueId1");
    }

    @Test
    void testGetNodeById_NodeDoesNotExist() {
        when(nodeRepository.findById("uniqueId1")).thenReturn(Optional.empty());

        Optional<Node> retrievedNode = nodeService.getNodeById("uniqueId1");

        assertFalse(retrievedNode.isPresent());
        verify(nodeRepository, times(1)).findById("uniqueId1");
    }

    @Test
    void testDeleteNode() {
        doNothing().when(nodeRepository).deleteById("uniqueId1");

        nodeService.deleteNode("uniqueId1");

        verify(nodeRepository, times(1)).deleteById("uniqueId1");
    }
}
```

---

### **Explanation**

1. **Setup:**
   - Use `@Mock` to mock the `NodeRepository`.
   - Use `@InjectMocks` to inject the mock into the `NodeService`.
   - Initialize the mocks with `MockitoAnnotations.openMocks()` in the `@BeforeEach` method.

2. **Test Cases:**
   - **`testSaveNode`**:
     - Mock the `save` method of the repository to return the given `Node`.
     - Validate the response and verify the `save` method was called exactly once.
   - **`testGetAllNodes`**:
     - Mock `findAll` to return a list of nodes.
     - Validate the response and verify the `findAll` method was called.
   - **`testGetNodeById_NodeExists`**:
     - Mock `findById` to return an `Optional` containing a node.
     - Validate the response to ensure the `Optional` is present and matches the mock.
   - **`testGetNodeById_NodeDoesNotExist`**:
     - Mock `findById` to return an empty `Optional`.
     - Validate the response to ensure the `Optional` is empty.
   - **`testDeleteNode`**:
     - Mock `deleteById` to perform no action (`doNothing`).
     - Verify that `deleteById` was called with the correct argument.

3. **Assertions and Verifications:**
   - Use `assertNotNull`, `assertEquals`, `assertTrue`, and `assertFalse` to validate the responses.
   - Use `verify` to ensure the mocked methods were called with the correct arguments and the expected number of times.

