      <div>
        <strong>Metadata:</strong>
        {Object.keys(node.metadata).length > 0 ? (
          <ul style={{ paddingLeft: "20px" }}>
            {Object.entries(node.metadata).map(([key, value], index) => (
              <li key={index}>
                <strong>{key}:</strong> {value}
