Yes, there are several alternatives to `three.js` for creating 3D animations and graphics. Here are some notable ones:

---

### 1. **Babylon.js**
- A powerful 3D engine, similar to `three.js`, but provides more built-in features for creating interactive 3D experiences.
- Highly suitable for both beginners and advanced developers.

#### Example with Babylon.js (Rotating Sphere)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Babylon.js Animated Sphere</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <canvas id="renderCanvas"></canvas>
  <script src="https://cdn.babylonjs.com/babylon.js"></script>
  <script>
    const canvas = document.getElementById('renderCanvas');
    const engine = new BABYLON.Engine(canvas, true);

    // Create scene
    const createScene = () => {
      const scene = new BABYLON.Scene(engine);

      // Camera
      const camera = new BABYLON.ArcRotateCamera(
        'Camera',
        Math.PI / 2,
        Math.PI / 4,
        5,
        BABYLON.Vector3.Zero(),
        scene
      );
      camera.attachControl(canvas, true);

      // Light
      const light = new BABYLON.HemisphericLight('Light', new BABYLON.Vector3(0, 1, 0), scene);

      // Sphere
      const sphere = BABYLON.MeshBuilder.CreateSphere('sphere', { diameter: 2, segments: 32 }, scene);

      // Material
      const material = new BABYLON.StandardMaterial('material', scene);
      material.diffuseColor = new BABYLON.Color3(0, 0.5, 1); // Blue color
      sphere.material = material;

      // Animation
      scene.registerBeforeRender(() => {
        sphere.rotation.y += 0.01; // Rotate around the y-axis
      });

      return scene;
    };

    const scene = createScene();

    // Render loop
    engine.runRenderLoop(() => {
      scene.render();
    });

    // Resize handling
    window.addEventListener('resize', () => {
      engine.resize();
    });
  </script>
</body>
</html>
```

