### 1. Updated HOC for Modal

The updated HOC will allow passing children and abstract only the common logic.

```tsx
// withFormModal.tsx

import React, { useState } from "react";

interface FormModalProps {
  title: string;
  onSubmit: () => void;
  onClose: () => void;
  submitButtonLabel: string;
  isError: boolean;
  errorMessage: string;
}

const withFormModal = <P extends object>(
  WrappedComponent: React.ComponentType<P>
) => {
  const FormModal: React.FC<P & FormModalProps> = ({
    title,
    onSubmit,
    onClose,
    submitButtonLabel,
    isError,
    errorMessage,
    ...props
  }) => {
    return (
      <div>
        <h2>{title}</h2>
        {/* Error Handling */}
        {isError && <div style={{ color: "red" }}>{errorMessage}</div>}

        {/* Render the form or content via WrappedComponent */}
        <WrappedComponent {...(props as P)} />

        <button type="button" onClick={onSubmit}>
          {submitButtonLabel}
        </button>
        <button type="button" onClick={onClose}>
          Cancel
        </button>
      </div>
    );
  };

  return FormModal;
};

export default withFormModal;
```

### 2. Modify Modals to Use the HOC

Now, each modal will define only the required fields and form-specific logic, while the HOC handles the common logic like error handling, submission, and modal control.

