### `App.tsx`

```typescript
import React, { useState, useEffect } from "react";
import ProblemsList from "./components/ProblemsList";
import ProblemDetail from "./components/ProblemDetail";
import UpsertProblemModal from "./components/UpsertProblemModal";
import UpsertDescriptionModal from "./components/UpsertDescriptionModal";
import UpsertSolutionModal from "./components/UpsertSolutionModal";
import { getProblems } from "./components/api";

const App: React.FC = () => {
  const [problems, setProblems] = useState<any[]>([]);
  const [selectedProblemId, setSelectedProblemId] = useState<string | null>(null);
  const [showUpsertProblemModal, setShowUpsertProblemModal] = useState<boolean>(false);
  const [showUpsertDescriptionModal, setShowUpsertDescriptionModal] = useState<boolean>(false);
  const [showUpsertSolutionModal, setShowUpsertSolutionModal] = useState<boolean>(false);
  const [currentProblemId, setCurrentProblemId] = useState<string | null>(null);

  useEffect(() => {
    const fetchProblems = async () => {
      const data = await getProblems();
      setProblems(data);
    };
    fetchProblems();
  }, []);

  const openUpsertProblemModal = (problemId?: string) => {
    setCurrentProblemId(problemId || null);
    setShowUpsertProblemModal(true);
  };

  const closeUpsertProblemModal = () => {
    setShowUpsertProblemModal(false);
    setCurrentProblemId(null);
  };

  const openUpsertDescriptionModal = (problemId: string) => {
    setCurrentProblemId(problemId);
    setShowUpsertDescriptionModal(true);
  };

  const closeUpsertDescriptionModal = () => {
    setShowUpsertDescriptionModal(false);
    setCurrentProblemId(null);
  };

  const openUpsertSolutionModal = (problemId: string) => {
    setCurrentProblemId(problemId);
    setShowUpsertSolutionModal(true);
  };

  const closeUpsertSolutionModal = () => {
    setShowUpsertSolutionModal(false);
    setCurrentProblemId(null);
  };

  const handleProblemSuccess = () => {
    setShowUpsertProblemModal(false);
    setSelectedProblemId(currentProblemId || "");
  };

  const handleDescriptionSuccess = () => {
    setShowUpsertDescriptionModal(false);
    setSelectedProblemId(currentProblemId || "");
  };

  const handleSolutionSuccess = () => {
    setShowUpsertSolutionModal(false);
    setSelectedProblemId(currentProblemId || "");
  };

  return (
    <div>
      <h1>Problem Management</h1>
      <ProblemsList />
      {selectedProblemId && (
        <ProblemDetail problemId={selectedProblemId} />
      )}

      {/* Upsert Problem Modal */}
      {showUpsertProblemModal && (
        <UpsertProblemModal
          onClose={closeUpsertProblemModal}
          onSuccess={handleProblemSuccess}
          problemId={currentProblemId}
        />
      )}

      {/* Upsert Description Modal */}
      {showUpsertDescriptionModal && (
        <UpsertDescriptionModal
          onClose={closeUpsertDescriptionModal}
          onSuccess={handleDescriptionSuccess}
          problemId={currentProblemId || ""}
        />
      )}

      {/* Upsert Solution Modal */}
      {showUpsertSolutionModal && (
        <UpsertSolutionModal
          onClose={closeUpsertSolutionModal}
          onSuccess={handleSolutionSuccess}
          problemId={currentProblemId || ""}
        />
      )}

      <button onClick={() => openUpsertProblemModal()}>Create Problem</button>
    </div>
  );
};

export default App;
```

