```tsx
import React, { useState } from "react";
import { Problem } from "../models/Problem";
import axios from "axios";

interface Props {
  problem?: Problem;
  onClose: () => void;
  onSave: () => void;
}

const UpsertProblemModal: React.FC<Props> = ({ problem, onClose, onSave }) => {
  const [form, setForm] = useState<Problem>(problem || { title: "", status: "OPEN" });

  const handleSubmit = () => {
    if (form.id) {
      axios.put(`/api/problems/${form.id}`, form).then(() => onSave());
    } else {
      axios.post("/api/problems", form).then(() => onSave());
    }
  };

  return (
    <div className="modal">
      <h2>{form.id ? "Edit Problem" : "Create Problem"}</h2>
      <input
        type="text"
        placeholder="Title"
        value={form.title}
        onChange={(e) => setForm({ ...form, title: e.target.value })}
      />
      <select
        value={form.status}
        onChange={(e) => setForm({ ...form, status: e.target.value as Problem["status"] })}
      >
        <option value="OPEN">Open</option>
        <option value="IN_PROGRESS">In Progress</option>
        <option value="RESOLVED">Resolved</option>
        <option value="CLOSED">Closed</option>
      </select>
      <button onClick={handleSubmit}>Save</button>
      <button onClick={onClose}>Cancel</button>
    </div>
  );
};

export default UpsertProblemModal;
