  UPSERT_DESCRIPTION_FAILURE,
  UPSERT_SOLUTION_SUCCESS,
  UPSERT_SOLUTION_FAILURE
} from "./problemActions";

// Fetch all problems
export const getProblems = async (dispatch: any) => {
  dispatch({ type: "FETCH_PROBLEMS_REQUEST" });

