    dispatch({ type: FETCH_PROBLEM_SUCCESS, payload: problem });
  } catch (error) {
    dispatch({ type: FETCH_PROBLEM_FAILURE, payload: error.message });
  }
};

// Upsert a problem (create or update)
export const upsertProblem = async (problem: { title: string, status: string, id?: string }, dispatch: any) => {
  dispatch({ type: "UPSERT_PROBLEM_REQUEST" });

  try {
    const savedProblem = await apiRequest<{ title: string; status: string }, Problem>(
