// Upsert a solution for a problem
export const upsertSolution = async (problemId: string, solution: { solutionDetail: string; id?: string }, dispatch: any) => {
  dispatch({ type: "UPSERT_SOLUTION_REQUEST" });

  try {
    const updatedProblem = await apiRequest<{ solutionDetail: string; id?: string }, Problem>(
      "post",
      `/problems/${problemId}/solutions`,
