To extract the common component, we can create a reusable `UpsertModal` component that handles common functionality for adding and editing items. We can abstract the form logic to handle any type of data like `description`, `problem`, or `solution`, and simply pass the relevant fields as props. The modal can be reused for multiple use cases, while keeping the existing modal components intact.

Here’s how to refactor the code:

### 1. Create a Common `UpsertModal` Component

#### `UpsertModal.tsx` (Common Component)
```tsx
import React, { useState } from "react";
import styles from "./UpsertModal.module.css";

interface UpsertModalProps<T> {
  onClose: () => void;
  onSuccess: () => void;
  entityId?: string;
  initialData: T;
  submitAction: (data: T) => Promise<{ isError: boolean; message: string }>;
  entityType: string;
}

const UpsertModal = <T,>({
  onClose,
  onSuccess,
  entityId,
  initialData,
  submitAction,
  entityType,
}: UpsertModalProps<T>) => {
  const [data, setData] = useState<T>(initialData);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async () => {
    const { isError, message } = await submitAction(data);
    if (isError) {
      setError(message);
    } else {
      onSuccess();
      onClose();
    }
  };

  return (
    <div className={styles.container}>
      <h2 className={styles.heading}>
        {entityId ? `Update ${entityType}` : `Create ${entityType}`}
      </h2>
      {error && <p className={styles.error}>{error}</p>}
      <form>
        {/* Render fields dynamically */}
        {Object.keys(initialData).map((key) => (
          <div key={key}>
            <label>
              {key.charAt(0).toUpperCase() + key.slice(1)}:
              <input
                className={styles.input}
                value={(data as any)[key]}
                onChange={(e) => setData({ ...data, [key]: e.target.value })}
              />
            </label>
          </div>
        ))}
        <div>
          <button
            type="button"
            className={styles.submitButton}
            onClick={handleSubmit}
          >
            Submit
          </button>
