        Problem existingProblem = problemRepository.findById(problem.getId()).orElse(new Problem());
        existingProblem.setTitle(Optional.ofNullable(problem.getTitle()).orElse(existingProblem.getTitle()));
        existingProblem.setStatus(Optional.ofNullable(problem.getStatus()).orElse(existingProblem.getStatus()));

        return problemRepository.save(existingProblem);
