import org.springframework.stereotype.Service;

@Service
@RequiredArgsConstructor
public class ProblemService {

  private final ProblemRepository problemRepository;

  private static final Function<Problem, Boolean> upsertProblemValidator =
      problem -> {
        if (problem == null) {
          throw new CustomValidationException("Problem object should not be null");
        }
        if (problem.getTitle() == null || problem.getTitle().trim().isEmpty()) {
          throw new CustomValidationException("Problem title should not be empty or null");
        }
        return true;
      };

  private static final Function<ProblemDescription, Boolean> upsertDescriptionValidator =
      description -> {
        if (description == null) {
          throw new CustomValidationException("ProblemDescription object should not be null");
        }
        if (description.getDetail() == null || description.getDetail().trim().isEmpty()) {
          throw new CustomValidationException(
              "ProblemDescription detail should not be empty or null");
        }
        return true;
      };

  private static final Function<ProblemPossibleSolution, Boolean>
      upsertProblemPossibleSolutionValidator =
          solution -> {
            if (solution == null) {
              throw new CustomValidationException("ProblemSolution object should not be null");
            }
            if (solution.getSolutionDetail() == null
                || solution.getSolutionDetail().trim().isEmpty()) {
              throw new CustomValidationException(
                  "ProblemSolution detail should not be empty or null");
            }
            return true;
          };

  // Get all problems
  public List<Problem> getAllProblems() {
    return problemRepository.findAll();
  }

  // Get problem by ID
  public Optional<Problem> getProblemById(String id) {
    return problemRepository.findById(id);
  }

  // Upsert a problem (create or update)
  public Problem upsertProblem(Problem problem) {
    upsertProblemValidator.apply(problem);
    Problem existingEntity = problemRepository.findById(problem.getId()).orElse(new Problem());
    existingEntity.setTitle(
        problem.getTitle() != null ? problem.getTitle() : existingEntity.getTitle());
    existingEntity.setStatus(
        problem.getStatus() != null ? problem.getStatus() : existingEntity.getStatus());
    return problemRepository.save(existingEntity);
  }

  // Add description to a problem
  public Optional<Problem> upsertDescriptionToProblem(
      String problemId, ProblemDescription updatedDescription) {
    upsertDescriptionValidator.apply(updatedDescription);
    Optional<Problem> problem = problemRepository.findById(problemId);

    problem.ifPresent(
        p -> {
          List<ProblemDescription> descriptions = p.getDescriptions();

          // Check if the description already exists
          boolean exists =
              descriptions.stream()
                  .anyMatch(desc -> desc.getId().equals(updatedDescription.getId()));

          if (exists) {
            // Update existing description
            descriptions.stream()
                .filter(desc -> desc.getId().equals(updatedDescription.getId()))
                .findFirst()
                .ifPresent(
                    desc -> {
                      desc.setDetail(updatedDescription.getDetail());
                      //                      desc.setLanguage(updatedDescription.getLanguage());
                    });
          } else {
            // Add new description with auto-generated ID if ID is null or blank
            if (StringUtils.isBlank(updatedDescription.getId())) {
              updatedDescription.setId(new ObjectId().toString());
            }
            // Add new description if it doesn't exist
            descriptions.add(updatedDescription);
          }

          // Save the updated problem entity
          problemRepository.save(p);
        });

    return problem;
  }

  // Add solution to a problem
  public Optional<Problem> addSolutionToProblem(
      String problemId, ProblemPossibleSolution updatedSolution) {
    upsertProblemPossibleSolutionValidator.apply(updatedSolution);
    //    Optional<Problem> problem = problemRepository.findById(problemId);
    //    problem.ifPresent(
