    //    return problem;

    Optional<Problem> problem = problemRepository.findById(problemId);

    problem.ifPresent(
        p -> {
          List<ProblemPossibleSolution> solutions = p.getSolutions();

          // Check if the Solution already exists
          boolean exists =
              solutions.stream().anyMatch(desc -> desc.getId().equals(updatedSolution.getId()));

          if (exists) {
            // Update existing Solution
            solutions.stream()
                .filter(desc -> desc.getId().equals(updatedSolution.getId()))
                .findFirst()
                .ifPresent(
