```java
package com.p.problem.mgmt.nosql.controller;

import com.p.problem.mgmt.nosql.exception.ProblemNotFoundException;
import com.p.problem.mgmt.nosql.exception.DescriptionNotFoundException;
import com.p.problem.mgmt.nosql.exception.SolutionNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

@RestControllerAdvice
public class ControlAdvice {

    @ExceptionHandler(ProblemNotFoundException.class)
    public ResponseEntity<String> handleProblemNotFound(ProblemNotFoundException ex) {
        return new ResponseEntity<>(ex.getMessage(), HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler(DescriptionNotFoundException.class)
    public ResponseEntity<String> handleDescriptionNotFound(DescriptionNotFoundException ex) {
        return new ResponseEntity<>(ex.getMessage(), HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler(SolutionNotFoundException.class)
    public ResponseEntity<String> handleSolutionNotFound(SolutionNotFoundException ex) {
        return new ResponseEntity<>(ex.getMessage(), HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<String> handleGeneralException(Exception ex) {
        return new ResponseEntity<>(ex.getMessage(), HttpStatus.INTERNAL_SERVER_ERROR);
    }
}
```

