### Step 1: Create a Generic Form Component

Let's create a generic form component `UpsertModalForm.tsx`, which will handle the form fields, submission logic, and error handling.

```tsx
// src/common/components/UpsertModalForm.tsx

import React, { useState } from "react";
import styles from "./UpsertModalForm.module.css"; // Define a shared styles file

interface UpsertModalFormProps<T> {
  onClose: () => void;
  onSuccess: () => void;
  onSubmit: (data: T) => Promise<{ isError: boolean; message: string }>;
  initialData?: T;
  submitButtonText: string;
  formFields: Array<{
    label: string;
    value: string;
    onChange: (value: string) => void;
    placeholder?: string;
    type: string;
  }>;
  formTitle: string;
}

const UpsertModalForm = <T extends {}>({
  onClose,
  onSuccess,
  onSubmit,
  initialData = {} as T,
  submitButtonText,
  formFields,
  formTitle,
}: UpsertModalFormProps<T>) => {
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<T>(initialData);

  const handleSubmit = async () => {
    const { isError, message } = await onSubmit(formData);
    if (isError) {
      setError(message);
    } else {
      onSuccess();
      onClose();
    }
  };

  return (
    <div className={styles.container}>
      <h2 className={styles.heading}>{formTitle}</h2>
      {error && <p className={styles.error}>{error}</p>}
      <form>
        {formFields.map((field, idx) => (
          <label key={idx}>
            {field.label}:
            {field.type === "textarea" ? (
              <textarea
                className={styles.textarea}
                value={formData[field.value as keyof T] as string}
                onChange={(e) => {
                  const newFormData = { ...formData };
                  newFormData[field.value as keyof T] = e.target.value;
                  setFormData(newFormData);
                  field.onChange(e.target.value);
                }}
                placeholder={field.placeholder}
              />
            ) : (
              <input
                className={styles.input}
                value={formData[field.value as keyof T] as string}
                onChange={(e) => {
                  const newFormData = { ...formData };
                  newFormData[field.value as keyof T] = e.target.value;
                  setFormData(newFormData);
                  field.onChange(e.target.value);
                }}
                type={field.type}
                placeholder={field.placeholder}
              />
            )}
          </label>
        ))}
        <div>
          <button type="button" className={styles.submitButton} onClick={handleSubmit}>
            {submitButtonText}
          </button>
          <button type="button" className={styles.cancelButton} onClick={onClose}>
            Cancel
          </button>
        </div>
      </form>
    </div>
  );
};

export default UpsertModalForm;
```

