Here is the implementation for the `FormElement.tsx` component and its associated `FormElement.module.css`. This component dynamically renders a form element (`input`, `textarea`, or `select`) based on the `as` prop and passes additional props to the target element.

---

### `FormElement.tsx`

```tsx
import React from "react";
import styles from "./FormElement.module.css";

interface FormElementProps {
  as: "input" | "textarea" | "select";
  [key: string]: any; // Props for the target element
}

const FormElement: React.FC<FormElementProps> = ({ as, ...props }) => {
  switch (as) {
    case "textarea":
      return <textarea className={styles.textarea} {...props} />;
    case "select":
      return <select className={styles.select} {...props} />;
    case "input":
    default:
      return <input className={styles.input} {...props} />;
  }
};

export default FormElement;
```

