            {desc.language}: {desc.detail}
          </li>
        ))}
      </ul>
      <h3>Solutions</h3>
      <ul>
        {problem.solutions.map((solution, index) => (
          <li key={index}>
            {solution.createdBy}: {solution.solutionDetail}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ProblemDetail;
