import { useParams } from "react-router-dom";
import { getProblemById } from "../api";
import styles from "./ProblemDetail.module.css"; // Import the CSS module

interface Problem {
  id: string;
  title: string;
  status: string;
  descriptions: { detail: string; language: string }[];
  solutions: { solutionDetail: string; createdBy: string }[];
