```typescript
import axios from "axios";
import { apiRequest } from "../../common/utils/apiClient";
import { type APISubmitResponseProps } from "./APIClientForms";

// Utility function for response handling
const handleResponse = async (response: Response | { data: unknown; headers: Record<string, string | null> }) => {
  const contentType = response.headers["content-type"] || response.headers.get?.("Content-Type");

  if (contentType?.includes("application/json")) {
    return response.data || (await response.json());
  }

  return response.data || (await response.text());
};

// Utility function for logging
const logRequest = (url: string, data: unknown) => {
  console.log("Request URL:", url, "Response Data:", data);
};

// Common return type
type ApiResponse<T> = {
  data: T | null;
  error: unknown;
};

// Axios-based implementation
export const getDetailsWithAxios = async <T = unknown>({
  method,
  url,
}: APISubmitResponseProps): Promise<ApiResponse<T>> => {
  try {
    const response = await axios({ method: method.toLowerCase(), url });
    const responseData = await handleResponse(response);

    logRequest(url, responseData);

    return { data: responseData as T, error: null };
  } catch (err) {
    console.error("Error with Axios:", err);
    return { data: null, error: err };
  }
};

// API client implementation
export const getDetailsWithApiClient = async <T = unknown>({
  method,
  url,
}: APISubmitResponseProps): Promise<ApiResponse<T>> => {
  try {
    const response = await apiRequest({ method: method.toLowerCase(), url });
    const responseData = await handleResponse(response);

    logRequest(url, responseData);

    return { data: responseData as T, error: null };
  } catch (err) {
    console.error("Error with ApiClient:", err);
    return { data: null, error: err };
  }
};

// Fetch-based implementation
export const getDetailsWithFetch = async <T = unknown>({
  method,
  url,
}: APISubmitResponseProps): Promise<ApiResponse<T>> => {
  try {
    const response = await fetch(url, { method });
    const responseData = await handleResponse(response);

    logRequest(url, responseData);

    return { data: responseData as T, error: null };
  } catch (err) {
    console.error("Error with Fetch:", err);
    return { data: null, error: err };
  }
};
```

