import { FormEvent, useState } from "react";
import axios from "axios";

const APIResponseAxiosTester = () => {
  const options = ["GET", "PUT", "POST", "DELETE", "PATCH"];
  const [data, setData] = useState<unknown>();
  const [error, setError] = useState<unknown>();

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    const formData = new FormData(e.target as HTMLFormElement);
    const method = formData.get("method") as string;
    const base = formData.get("base") as string;
    const url = formData.get("url") as string;

    try {
      const response = await axios({
        method: method.toLowerCase() as any, // Ensure method is lowercase for Axios
        url: `${base}${url}`,
      });

      const contentType = response.headers["content-type"];

      let responseData;
      if (contentType && contentType.includes("application/json")) {
        responseData = response.data; // Axios parses JSON responses automatically
      } else {
        responseData = response.data; // Fallback for other content types
      }

      console.log("Request URL:", `${base}${url}`, "Response Data:", responseData);
      setData(responseData);
      setError(null); // Clear previous errors if the response succeeds
    } catch (err) {
      console.error("Error:", err);
      setError(err);
      setData(null); // Clear previous data if there's an error
    }
  };

  return (
    <div>
      <h2>API Response Tester</h2>
      <form onSubmit={handleSubmit}>
        <label>
          Method:
          <select name="method" required>
            {options.map((opt) => (
              <option key={opt} value={opt}>
                {opt}
              </option>
            ))}
          </select>
        </label>
        <br />
        <label>
          Base URL:
          <input
            type="text"
            name="base"
            placeholder="Enter Base URL"
            required
          />
        </label>
        <br />
        <label>
          Resource URL:
          <input
            type="text"
            name="url"
            placeholder="Enter Resource URL"
            required
          />
        </label>
        <br />
        <div>
          <button type="submit">Submit</button>
        </div>
      </form>

      <h3>Response</h3>
      <pre>
        Data: <br />
        {JSON.stringify(data, null, 2)}
      </pre>
      <pre>
        Error: <br />
        {JSON.stringify(error, null, 2)}
      </pre>
    </div>
  );
};

export default APIResponseAxiosTester;
```

### Key Updates:
1. **Using Axios**:
   - Replaced `fetch` with `axios`.
