import { notify, updateNotification } from "./toast-utils";
import { useDispatch } from "react-redux";
import {
  hideBackdrop,
  showBackdrop,
} from "../../../redux/slices/backdropSlice";

// Utility: Validate if the argument is a function
const validateFunction = (fn, name = "argument") => {
  if (typeof fn !== "function") {
    throw new Error(`Provided ${name} is not a function`);
  }
};

// Utility: Validate if the argument is a Promise
const validatePromise = (promise, name = "Promise") => {
  if (!(promise instanceof Promise)) {
    throw new Error(`Provided ${name} must return a Promise`);
  }
};

// Utility: Validate if the result is a boolean
const validateBoolean = (result) => {
  if (typeof result !== "boolean") {
    throw new Error("Validator function must return a boolean result");
  }
};

// Utility: Validate if the promise resolves to the expected structure
const validatePromiseResult = (result) => {
  if (
    typeof result !== "object" ||
    result === null ||
    !("data" in result) ||
    !("isError" in result) ||
    !("message" in result)
  ) {
    throw new Error("Promise must resolve to the expected structure");
  }
};

// Default messages for API requests
const defaultMessages = {
  loadingMessage: "Loading, please wait...",
  successMessage: "Operation completed successfully!",
  failureMessage: "Operation failed. Please try again.",
  unexpectedErrorMessage:
    "An unexpected error occurred. Please contact support.",
};

// Utility: Prepare message or fallback to default
const prepareMessage = (message, defaultMessage) =>
  typeof message === "string" && message.trim() ? message : defaultMessage;

// Utility: Prepare error message from various input types
const prepareErrorMessage = (error, defaultMessage) => {
  if (!error) return defaultMessage;
  if (typeof error === "string" && error.trim()) return error;
  if (error.message && typeof error.message === "string" && error.message.trim())
    return error.message;
  try {
    return JSON.stringify(error);
  } catch {
    return defaultMessage;
  }
};

// Hook: Consolidated API execution utility
const useConsolidated = () => {
  const dispatch = useDispatch();

  /**
   * Execute an API request with validation, loading, and error handling.
   * @param {Function} apiRequest - Function that returns a Promise for the API request.
   * @param {Function} validatorFn - Function to validate input parameters or state.
   * @param {Object} messages - Custom messages for loading, success, failure, and error states.
   * @returns {Promise<{data: any, isError: boolean, message: string}>}
   */
  const executeApiRequest = async (
    apiRequest,
    validatorFn,
    {
      loadingMessage = "",
      successMessage = "",
      failureMessage = "",
      unexpectedErrorMessage = "",
    } = {}
  ) => {
    let toastId = null;

    try {
      // Validate input functions
      validateFunction(apiRequest, "apiRequest");
      validateFunction(validatorFn, "validatorFn");

      // Validate API request returns a Promise
      const apiRequestPromise = apiRequest();
      validatePromise(apiRequestPromise, "apiRequest");

      // Show loading notification and backdrop
      toastId = notify(
        prepareMessage(loadingMessage, defaultMessages.loadingMessage)
      );
      dispatch(showBackdrop());

      // Validate input state
      const isValid = validatorFn();
      validateBoolean(isValid);

      // Await API response
      const result = await apiRequestPromise;
      validatePromiseResult(result);

      // Destructure result
      const { data, isError, message } = result;

      // Update notification based on success or failure
      updateNotification(
        toastId,
        isError
          ? prepareMessage(failureMessage, defaultMessages.failureMessage)
          : prepareMessage(successMessage, defaultMessages.successMessage),
        isError ? LoaderStates.error : LoaderStates.success
      );

      return { data, isError, message };
    } catch (error) {
      // Handle unexpected errors
      const errorMessage = prepareErrorMessage(
        error,
        prepareMessage(
          unexpectedErrorMessage,
          defaultMessages.unexpectedErrorMessage
        )
      );

      updateNotification(toastId, errorMessage, LoaderStates.error);
      console.error("API Request Error:", error);

      return { data: null, isError: true, message: errorMessage };
    } finally {
      // Hide backdrop
      dispatch(hideBackdrop());
    }
  };

  return { executeApiRequest };
};

export default useConsolidated;
```

### Key Improvements
1. **Function Naming**: Renamed utility functions for clarity (e.g., `isFunction` → `validateFunction`).
2. **Message Preparation**: Simplified `prepareMessage` and ensured robust fallback to default values.
3. **Error Handling**: Centralized and simplified error message preparation in `prepareErrorMessage`.
4. **Reduced Redundancy**: Removed repetitive logging and conditional checks.
5. **Parameter Defaults**: Used destructuring with default values in the `executeApiRequest` parameters to reduce manual checks.
6. **Validation**: Abstracted input and result validation into smaller reusable functions (`validateFunction`, `validatePromise`, `validateBoolean`, `validatePromiseResult`).

This version is concise, reusable, and adheres to clean code practices.

