  onBaseSpanClick = () => {},
}) => {
  const { BreadcrumbItemType } = useGlobalServiceProvider();
  const [showDescr, setShowDescr] = useState(showDescription);
  const selectedElementRef = useRef(null);

  useEffect(() => {
    if (selectedElementRef.current) {
      selectedElementRef.current.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  }, [selectedSectionId]);

  const filteredTags = topic.tags?.map((uniqueId) =>
    tags.find((tag) => tag.uniqueId === uniqueId)
  );

  const traverseTopic = useCallback((increment) => {
    onTopicTraversal(increment);
  }, [onTopicTraversal]);

  return (
    <div>
      <ButtonGroup
        options={[
          { id: 1, children: "<<", title: "Previous", onClick: () => traverseTopic(-1) },
          { id: 2, children: ">>", title: "Next", onClick: () => traverseTopic(1) },
        ]}
      />
      <Breadcrumbs
        providedItem={topic}
        providedItemType={BreadcrumbItemType.TOPIC}
        ancestors={topic.ancestors}
        onAncestorClick={onAncestorClick}
        onBaseSpanClick={onBaseSpanClick}
      />
      <h3>{topic.name}</h3>

      {/* Topic Dates */}
      <div>
        <ListSection
          title="Tags:"
          items={filteredTags}
          errorMessage="No tags added yet!"
          renderItem={(tag) => (
            <span
              key={tag.uniqueId}
              style={{ margin: "5px", cursor: "pointer" }}
              onClick={() => onLinkedTagSelection(tag.uniqueId)}
            >
              {tag.title}
            </span>
          )}
        />
      </div>

      {/* Actions */}
      <ListSection
        title=""
        items={[
          { title: "Edit", action: onEdit },
          { title: !showDescr ? "Show Description" : "Hide Description", action: () => setShowDescr(!showDescr) },
          { title: "Add Subtopic", action: onAddSubTopic },
          { title: isPinned ? "Unpin Topic" : "Pin Topic", action: () => onPinTopic(topic, isPinned) },
        ]}
        renderItem={({ title, action }, idx) => (
          <CustomButton key={idx} onClick={action}>
            {title}
          </CustomButton>
        )}
      />

      {/* Floating Buttons */}
      <FloatingButton buttonText="Pinned Topics">
        <ListSection
          title="Pinned Topics"
          items={pinnedTopics}
          errorMessage="No pinned topics!"
          renderItem={(pinned) => (
            <div key={pinned.uniqueId} onClick={() => onChildTopicClick(pinned)}>
              {pinned.title}
            </div>
          )}
        />
      </FloatingButton>

      {/* Description */}
      {showDescr && (
        <ToggleablePanel
          title="Description"
          showContent={!!topic.description}
          panelContainerStyle={{ margin: "10px 0", padding: "10px", border: "1px solid #ccc" }}
        >
          {ReactHtmlParser(topic.description)}
        </ToggleablePanel>
      )}

      {/* Sections */}
      <ToggleablePanel
        title={`Sections (${topic.sections?.length || 0})`}
        showContent={topic.sections?.length > 0}
      >
        <ListSection
          items={topic.sections || []}
          errorMessage="No sections available."
          renderItem={(section) => (
            <div key={section.uniqueId} onClick={() => onChildTopicClick(section)}>
              {section.name}
            </div>
          )}
        />
      </ToggleablePanel>
    </div>
  );
};

export default TopicCard;
