import useArithmetic from "./hooks/useArithmetic";

const ArithmeticComponent = () => {
  const { add, subtract, multiply, divide } = useArithmetic();

  const handleCalculation = () => {
    console.log("Addition:", add(5, 3)); // 8
    console.log("Subtraction:", subtract(5, 3)); // 2
    console.log("Multiplication:", multiply(5, 3)); // 15
    console.log("Division:", divide(10, 2)); // 5
  };

