      <div className={styles.loaderContainer}>
        <div className={stateClass}></div>
        <h1 className={styles.title}>{title || defaultMessages[state]}</h1>
      </div>
    </>,
    document.body // Attach the loader to the body to avoid layout issues
  );
};

export default LoaderWithTitle;
