import React, { useEffect, useState } from "react";
import styles from "./styles.module.css";

const FallbackDuration = 5000; // Fallback duration in ms

const CustomBackdrop = ({ shouldActive = "no" }) => {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    let timer;

    if (shouldActive === "yes") {
      setIsVisible(true);
      // Set a fallback timer to auto-hide the backdrop after 5 seconds
      timer = setTimeout(() => {
        setIsVisible(false);
      }, FallbackDuration);
    } else {
      setIsVisible(false);
    }

    return () => clearTimeout(timer);
  }, [shouldActive]);

  if (!isVisible) return null;

  return <div className={styles.backdrop}></div>;
};

export default CustomBackdrop;
```

---

### Behavior
1. **Prop Control**:
   - When `shouldActive` is `"yes"`, the backdrop is shown immediately.
   - When `shouldActive` changes to anything other than `"yes"`, the backdrop hides.

2. **Auto-Hide**:
   - The backdrop will automatically hide after `5000ms` as a fallback even if `shouldActive` remains `"yes"`.

