          showBackdrop={false} /* Avoid multiple backdrops */
        />
      ),
    });
  };

  const fetchTaskDetailsForGivenId = async (/**id*/) => {
    const toastId = notify("Fetching Task Details For Given Id");
    const { data, isError, message } = await apiRequest({
      method: "get",
      url: `${BACKEND_APPLICATION_BASE_URL}/tags`,
    });

    updateNotification(
      toastId,
      null,
      isError ? LoaderStates.error : LoaderStates.success
    );

    return { data, isError, message };
  };

  const getRandomNumber = () => {
    const toastId = notify("Performing calculations for Random Number");
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        const randomNumber = Math.floor(Math.random() * 10) + 1;
        if (randomNumber < 11) {
          resolve({ randomNumber, isError: false, message: "" });
          updateNotification(
            toastId,
            "Calculations done successfully!!",
            LoaderStates.success
          );
        } else {
          reject({
            randomNumber: 103,
            isError: false,
            message: "Some error occurred",
          });
          updateNotification(
            toastId,
            "Some error occurred",
            LoaderStates.error
          );
        }
      }, 3000); // Delay of 3 seconds
    });
  };

  const doubleTheNumber = (number) => {
    const toastId = notify("Performing calculations to double the given Number");
    if (!Number.isInteger(number)) {
      updateNotification(toastId, "Not a number!!", LoaderStates.error);
      return 0;
    }
    updateNotification(
      toastId,
      "Calculations done successfully!!",
      LoaderStates.success
    );
    return number * 2;
  };

  return {
    fetchTaskDetailsForGivenId,
    getRandomNumber,
    doubleTheNumber,
    clearPreviousNotifications,
  };
};

export default useConsolidated;
```

