### **API Route - Create ThinkTankItem**
```ts
import express from "express";
import { ThinkTankItemModel, ThinkTankItemType } from "../models/ThinkTankItem";

const router = express.Router();

/**
 * @route   POST /think-tank
 * @desc    Create a new ThinkTankItem
 * @access  Public
 */
router.post("/", async (req, res) => {
  try {
    const { itemType, smartContent } = req.body;

    // Validate smartContent
    if (!smartContent || typeof smartContent !== "object" || !smartContent.content?.trim()) {
      return res.status(400).json({ error: "Invalid smartContent. 'content' field is required and cannot be empty." });
    }

    // Validate itemType or set default
    const validItemType = Object.values(ThinkTankItemType).includes(itemType) ? itemType : ThinkTankItemType.YetToBeDecided;

    // Create new ThinkTankItem
    const newItem = new ThinkTankItemModel({
      itemType: validItemType,
      smartContent,
    });

    const savedItem = await newItem.save();
    res.status(201).json(savedItem);
  } catch (error) {
    console.error("Error creating ThinkTankItem:", error);
    res.status(500).json({ error: "Internal Server Error" });
  }
});

export default router;
```

