### Refactored Code

```jsx
import React, { useMemo, useCallback } from "react";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate, useParams } from "react-router-dom";
import { BACKEND_APPLICATION_BASE_URL } from "../../../../common/constants/globalConstants";
import useDataFetching from "../../../../common/hooks/useDataFetching";
import {
  fetchPinnedItems,
  upsertPinnedItem,
} from "../../../../redux/slices/pinnedItemSlice";
import { fetchTags, selectAllFlatTags } from "../../../../redux/slices/tagsSlice";
import {
  selectAllFlatTasks,
  selectNextTaskUniqueId,
  selectPrevTaskUniqueId,
  setSelectedTaskUniqueId,
} from "../../../../redux/slices/taskSlice";
import TaskCard from "./TaskCard";

const ViewTaskRouterPage = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { id } = useParams();

  // Fetch task data
  const url = `${BACKEND_APPLICATION_BASE_URL}/tasks/${id}`;
  const { data, loading, error } = useDataFetching({ url });

  // Redux selectors
  const availableTags = useSelector(selectAllFlatTags);
  const pinnedItems = useSelector((state) => state.pinnedItems.data);
  const tasks = useSelector(selectAllFlatTasks);
  const nextTaskUniqueId = useSelector(selectNextTaskUniqueId);
  const prevTaskUniqueId = useSelector(selectPrevTaskUniqueId);

  // Derived state
  const pinnedTasks = useMemo(() => {
    if (!pinnedItems || !tasks) return [];
    return pinnedItems
      .filter((pi) => pi.linkedItemType === "task" && !pi.softDelete)
      .map((pi) => ({
        ...pi,
        title: tasks.find((task) => task.uniqueId === pi.linkedUniqueId)?.title || "",
      }));
  }, [pinnedItems, tasks]);

  const isPinned = useMemo(() => {
    return pinnedTasks.some((task) => task.linkedUniqueId === id);
  }, [pinnedTasks, id]);

  // Fetch tags and pinned items on mount
  useMemo(() => {
    dispatch(fetchTags());
    dispatch(fetchPinnedItems());
  }, [dispatch]);

  // Update selected task on ID change
  useMemo(() => {
    if (id) {
      dispatch(setSelectedTaskUniqueId(id));
    }
  }, [id, dispatch]);

  // Handlers
  const handleEdit = useCallback(() => {
    navigate(`/task-mgmt/${id}/edit`);
  }, [id, navigate]);

  const handleAddSubTask = useCallback(() => {
    navigate(`/task-mgmt/${id}/add-sub-task`);
  }, [id, navigate]);

  const handleChildTaskClick = useCallback(
    (item) => {
      navigate(`/task-mgmt/${item?.uniqueId}`);
    },
    [navigate]
  );

  const handleTaskTraversal = useCallback(
    (increment) => {
      if (increment === 1 && nextTaskUniqueId) {
        navigate(`/task-mgmt/${nextTaskUniqueId}`);
      } else if (increment === -1 && prevTaskUniqueId) {
        navigate(`/task-mgmt/${prevTaskUniqueId}`);
      }
    },
    [nextTaskUniqueId, prevTaskUniqueId, navigate]
  );

  const handleLinkedTagSelection = useCallback(
    (linkedTagUID) => {
      navigate(`/tags/${linkedTagUID}`);
    },
    [navigate]
  );

  const handlePinTask = useCallback(
    (item, isPinned) => {
      dispatch(
        upsertPinnedItem({
          linkedUniqueId: item.uniqueId,
          linkedItemType: "task",
          softDelete: isPinned,
        })
      );
    },
    [dispatch]
  );

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;

  return (
    <>
      {data ? (
        <TaskCard
          task={data}
          tags={availableTags}
          showDescription
          pinnedTasks={pinnedTasks}
          isPinned={isPinned}
          onEdit={handleEdit}
          onTaskTraversal={handleTaskTraversal}
          onAddSubTask={handleAddSubTask}
          onChildTaskClick={handleChildTaskClick}
          onPinTask={handlePinTask}
          onLinkedTagSelection={handleLinkedTagSelection}
        />
      ) : (
        <>No task data found for ID: {id}</>
      )}
    </>
  );
};

export default ViewTaskRouterPage;
```

