 * @param {Array} inputs - Array of objects with `key`, `value`, and `type`.
 */
const validateInputs = (inputs) => {
  inputs.forEach(({ key, value, type }) => {
    if (!value || typeof value !== type) {
      throw new Error(`Invalid ${key}: '${value}' provided. Expected ${type}.`);
    }
  });
};


