          {selectedIcon ? (
            <>
              <IconComponent className={styles.icon} />
              <div className={styles.buttonContainer}>
                <button
                  className={styles.button}
                  onClick={() => handleNavigation(-1)}
                  disabled={selectedIndex <= 0}
                >
                  Prev
