### Updated Code with Best Practices

```javascript
import React, { useEffect, useState, useCallback } from "react";

const DataFetcher = () => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Using useCallback for fetchData to prevent unnecessary re-creation
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch("https://jsonplaceholder.typicode.com/posts/1");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      setData(result);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, []);

  // Use useEffect to fetch data on mount
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Return loading, error, and data in a consistent structure
  if (loading) return <div aria-busy="true">Loading...</div>;
  if (error)
    return (
      <div role="alert" style={{ color: "red" }}>
        Error: {error}
      </div>
    );

  return (
    <div style={{ padding: "20px", fontFamily: "Arial, sans-serif" }}>
      <h1>Fetched Data</h1>
      <div>
        <strong>Title:</strong> {data.title}
      </div>
      <div>
        <strong>Body:</strong> {data.body}
      </div>
    </div>
  );
};

export default DataFetcher;
```

