 * @param {Object} params - The parameters for the API request.
 * @param {string} params.url - API endpoint URL.
 * @param {string} params.method - HTTP method (e.g., "get", "post").
 * @param {string} params.loadingMessage - Notification message for loading state.
 * @param {string} params.successMessage - Notification message for success state.
 * @param {string} params.failureMessage - Notification message for failure state.
 * @returns {Promise<{data: any, isError: boolean, message: string}>}
 */
const executeApiRequest = async ({
  url,
  method,
  loadingMessage,
  successMessage,
  failureMessage,
}) => {
  const toastId = notify(loadingMessage);
  const dispatch = useDispatch();

  dispatch(showBackdrop());

  try {
    const { data, isError, message } = await apiRequest({ method, url });

    updateNotification(
      toastId,
      isError ? failureMessage : successMessage,
      isError ? LoaderStates.error : LoaderStates.success
    );

